tool_schemas.implementation:
def get_workspace_hierarchy(workspaceId, includeArchived=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _oplog(workspace_id, tool_name, op_type, params, status, error_message=None, resolved=None, bulk=None, succ=None, fail=None):
        ops = _load("integration_operations.json")
        op_id = "op_" + uuid.uuid4().hex
        row = {
            "id": op_id,
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "operation_type": op_type,
            "request_params": params,
            "resolved_clickup_ids": resolved,
            "bulk_count": bulk,
            "succeeded_count": succ,
            "failed_count": fail,
            "status": status,
            "error_message": error_message,
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        ops.append(row)
        _save("integration_operations.json", ops)
        return row

    # Validate
    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
        _oplog(workspaceId if isinstance(workspaceId, str) else "unknown", "get_workspace_hierarchy", "read",
               {"workspaceId": workspaceId, "includeArchived": includeArchived}, "rejected",
               "workspaceId must match ^cu_wsp_[0-9A-Z]+$")
        return _err("VALIDATION_ERROR", "workspaceId must match required format")
    if includeArchived is not None and not isinstance(includeArchived, bool):
        _oplog(workspaceId, "get_workspace_hierarchy", "read",
               {"workspaceId": workspaceId, "includeArchived": includeArchived}, "rejected",
               "includeArchived must be boolean")
        return _err("VALIDATION_ERROR", "includeArchived must be a boolean")

    include_arch = bool(includeArchived) if includeArchived is not None else False

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws:
        _oplog(workspaceId, "get_workspace_hierarchy", "read",
               {"workspaceId": workspaceId, "includeArchived": includeArchived}, "failed",
               "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")

    # Enforce workspace status for read tool: allowed even if read_only; disabled still allowed for reads per rule? only says writes rejected; reads may proceed.
    # Implement: reads allowed for all statuses.
    # Freshness rule
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    last_sync = _parse_dt(ws.get("last_hierarchy_sync_at"))
    is_fresh = False
    if last_sync:
        age = datetime.datetime.utcnow() - last_sync
        # "fresh" threshold (service-defined). Use 10 minutes to behave dynamically.
        is_fresh = age.total_seconds() <= 600

    resolved = {}
    if is_fresh and isinstance(ws.get("hierarchy_snapshot"), dict):
        snap = ws.get("hierarchy_snapshot")
        # Filter archived if needed: snapshot assumed includes entities with status field
        if not include_arch:
            def _filter_entities(node):
                if isinstance(node, dict):
                    out = {}
                    for k, v in node.items():
                        if k in ("spaces", "folders", "lists", "entities"):
                            out[k] = _filter_entities(v)
                        else:
                            out[k] = _filter_entities(v)
                    # if this dict looks like an entity
                    if "status" in node and node.get("status") in ("archived", "deleted"):
                        return None
                    return out
                if isinstance(node, list):
                    outl = []
                    for it in node:
                        fi = _filter_entities(it)
                        if fi is None:
                            continue
                        outl.append(fi)
                    return outl
                return node

            filtered = _filter_entities(snap)
            snap = filtered if isinstance(filtered, dict) else {"snapshot": filtered}
        _oplog(workspaceId, "get_workspace_hierarchy", "read",
               {"workspaceId": workspaceId, "includeArchived": includeArchived}, "succeeded",
               None, resolved=resolved)
        return {
            "workspace_id": workspaceId,
            "clickup_team_id": ws.get("clickup_team_id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "last_hierarchy_sync_at": ws.get("last_hierarchy_sync_at"),
            "snapshot": snap,
            "refreshed": False,
            "latency_ms": int((time.time() - t0) * 1000),
        }

    # Refresh from hierarchy_entities and update snapshot + last_hierarchy_sync_at
    ents = _load("hierarchy_entities.json")
    ents_ws = [e for e in ents if e.get("workspace_id") == workspaceId and e.get("status") != "deleted"]
    if not include_arch:
        ents_ws = [e for e in ents_ws if e.get("status") == "active"]

    spaces = [e for e in ents_ws if e.get("entity_type") == "space" and e.get("parent_entity_id") in (None, "")]
    # Build maps
    by_id = {e.get("id"): e for e in ents_ws if isinstance(e.get("id"), str)}
    folders = [e for e in ents_ws if e.get("entity_type") == "folder"]
    lists = [e for e in ents_ws if e.get("entity_type") == "list"]

    folders_by_parent = {}
    for f in folders:
        pid = f.get("parent_entity_id")
        folders_by_parent.setdefault(pid, []).append(f)
    lists_by_parent = {}
    for l in lists:
        pid = l.get("parent_entity_id")
        lists_by_parent.setdefault(pid, []).append(l)

    def _entity_view(e):
        return {
            "id": e.get("id"),
            "entity_type": e.get("entity_type"),
            "clickup_id": e.get("clickup_id"),
            "space_clickup_id": e.get("space_clickup_id"),
            "parent_entity_id": e.get("parent_entity_id"),
            "name": e.get("name"),
            "content": e.get("content"),
            "archived": e.get("archived"),
            "override_statuses": e.get("override_statuses"),
            "status": e.get("status"),
            "raw": e.get("raw"),
            "updated_at": e.get("updated_at"),
        }

    snap_spaces = []
    for sp in sorted(spaces, key=lambda x: (x.get("name") or "", x.get("clickup_id") or "")):
        sp_id = sp.get("id")
        sp_node = _entity_view(sp)
        sp_folders = folders_by_parent.get(sp_id, [])
        sp_lists_direct = lists_by_parent.get(sp_id, [])

        folder_nodes = []
        for fol in sorted(sp_folders, key=lambda x: (x.get("name") or "", x.get("clickup_id") or "")):
            fol_id = fol.get("id")
            fol_node = _entity_view(fol)
            fol_lists = lists_by_parent.get(fol_id, [])
            fol_node["lists"] = [_entity_view(li) for li in sorted(fol_lists, key=lambda x: (x.get("name") or "", x.get("clickup_id") or ""))]
            folder_nodes.append(fol_node)

        sp_node["folders"] = folder_nodes
        sp_node["lists"] = [_entity_view(li) for li in sorted(sp_lists_direct, key=lambda x: (x.get("name") or "", x.get("clickup_id") or ""))]
        snap_spaces.append(sp_node)

    snapshot = {"spaces": snap_spaces}

    # Persist into workspace row
    ws["hierarchy_snapshot"] = snapshot
    ws["last_hierarchy_sync_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ws["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for i, w in enumerate(workspaces):
        if w.get("id") == workspaceId:
            workspaces[i] = ws
            break
    _save("workspaces.json", workspaces)

    _oplog(workspaceId, "get_workspace_hierarchy", "read",
           {"workspaceId": workspaceId, "includeArchived": includeArchived}, "succeeded",
           None, resolved=resolved)

    return {
        "workspace_id": workspaceId,
        "clickup_team_id": ws.get("clickup_team_id"),
        "name": ws.get("name"),
        "status": ws.get("status"),
        "last_hierarchy_sync_at": ws.get("last_hierarchy_sync_at"),
        "snapshot": snapshot,
        "refreshed": True,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def create_task(workspaceId, name, listId=None, listName=None, parent=None, description=None, status=None, priority=None, dueDate=None, startDate=None, assignees=None, tags=None, customFields=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 string", field=field)
        v = s.strip()
        try:
            datetime.datetime.fromisoformat(v[:-1] if v.endswith("Z") else v)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be ISO 8601 date-time", field=field)
        return v, None

    t0 = time.time()
    started_at = _now()

    # Validate basic inputs (relax workspaceId: may be internal id OR ClickUp team id; do not enforce regex here)
    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")
    if not isinstance(name, str) or not name.strip():
        # must still log op; continue to resolution then reject
        name_err = _err("VALIDATION_ERROR", "name is required", field="name")
    else:
        name_err = None

    if listId is None and (listName is None or (isinstance(listName, str) and not listName.strip())):
        list_err = _err("VALIDATION_ERROR", "Either listId or listName is required", field="listId")
    else:
        list_err = None

    if priority is not None:
        if not isinstance(priority, int):
            pr_err = _err("VALIDATION_ERROR", "priority must be an integer", field="priority")
        elif priority < 1 or priority > 5:
            pr_err = _err("VALIDATION_ERROR", "priority must be between 1 and 5", field="priority")
        else:
            pr_err = None
    else:
        pr_err = None

    if assignees is not None and not (isinstance(assignees, list) and all(isinstance(x, str) for x in assignees)):
        asg_err = _err("VALIDATION_ERROR", "assignees must be an array of strings", field="assignees")
    else:
        asg_err = None

    if tags is not None and not (isinstance(tags, list) and all(isinstance(x, str) for x in tags)):
        tag_err = _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")
    else:
        tag_err = None

    cf_err = None
    if customFields is not None:
        if not isinstance(customFields, list):
            cf_err = _err("VALIDATION_ERROR", "customFields must be an array of {id,value}", field="customFields")
        else:
            for i, it in enumerate(customFields):
                if not isinstance(it, dict):
                    cf_err = _err("VALIDATION_ERROR", "customFields items must be objects", field="customFields")
                    break
                if "id" not in it or "value" not in it:
                    cf_err = _err("VALIDATION_ERROR", "customFields items must include id and value", field="customFields")
                    break
                if not isinstance(it.get("id"), str) or not it.get("id").strip():
                    cf_err = _err("VALIDATION_ERROR", "customFields.id must be a non-empty string", field="customFields")
                    break
                # value may be null/any; accept as-is

    due_v, due_e = _parse_dt(dueDate, "dueDate")
    if due_e:
        due_err = due_e
    else:
        due_err = None
    start_v, start_e = _parse_dt(startDate, "startDate")
    if start_e:
        start_err = start_e
    else:
        start_err = None

    # Resolve workspace (try internal id first, then clickup_team_id)
    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "create_task",
            "operation_type": "write",
            "request_params": {
                "workspaceId": workspaceId,
                "listId": listId,
                "listName": listName,
                "parent": parent,
                "name": name,
                "description": description,
                "status": status,
                "priority": priority,
                "dueDate": dueDate,
                "startDate": startDate,
                "assignees": assignees,
                "tags": tags,
                "customFields": customFields,
            },
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    # Workspace write policy
    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    if name_err or list_err or pr_err or asg_err or tag_err or cf_err or due_err or start_err:
        first = name_err or list_err or pr_err or asg_err or tag_err or cf_err or due_err or start_err
        _op_write("rejected", first["error"]["message"], resolved=None)
        return first

    # Resolve destination list entity
    ents = _rows(_load("hierarchy_entities.json"))
    resolved = {}
    list_ent = None
    if listId is not None and isinstance(listId, str) and listId.strip():
        lid = listId.strip()
        # Accept either internal entity id or ClickUp list clickup_id
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("workspace_id") != ws_id:
                continue
            if e.get("entity_type") != "list":
                continue
            if e.get("status") != "active":
                continue
            if e.get("id") == lid or e.get("clickup_id") == lid:
                list_ent = e
                break
        if list_ent is None and listName:
            # fall back to listName if provided
            pass
        else:
            resolved["listId"] = lid
            if list_ent:
                resolved["listEntityId"] = list_ent.get("id")
                resolved["listClickupId"] = list_ent.get("clickup_id")
    if list_ent is None:
        if not isinstance(listName, str) or not listName.strip():
            _op_write("rejected", "Either listId or listName is required", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "Either listId or listName is required", field="listId")
        lname = listName.strip()
        matches = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == lname]
        # Ambiguity rule: reject if multiple without further scoping (this tool has none)
        if len(matches) == 0:
            _op_write("failed", "Destination list not found", resolved={"listName": lname})
            return _err("NOT_FOUND", "Destination list not found", field="listName")
        if len(matches) > 1:
            _op_write("rejected", "listName is ambiguous; provide listId", resolved={"listName": lname, "matchCount": len(matches)})
            return _err("CONFLICT", "listName is ambiguous; provide listId", field="listName", matchCount=len(matches))
        list_ent = matches[0]
        resolved.update({"listName": lname, "listEntityId": list_ent.get("id"), "listClickupId": list_ent.get("clickup_id")})

    # Resolve parent task if provided (accept internal task id, clickup_task_id, or custom_id)
    tasks_rows = _rows(_load("tasks.json"))
    parent_task_row = None
    if parent is not None:
        if not isinstance(parent, str) or not parent.strip():
            _op_write("rejected", "parent must be a non-empty string when provided", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "parent must be a non-empty string when provided", field="parent")
        p = parent.strip()
        for tr in tasks_rows:
            if not isinstance(tr, dict):
                continue
            if tr.get("workspace_id") != ws_id:
                continue
            if tr.get("status") != "active":
                continue
            if tr.get("id") == p or tr.get("clickup_task_id") == p or (tr.get("custom_id") and tr.get("custom_id") == p):
                parent_task_row = tr
                break
        if parent_task_row is None:
            _op_write("failed", "Parent task not found", resolved={**resolved, "parent": p})
            return _err("NOT_FOUND", "Parent task not found", field="parent")
        # Prevent self-cycle (new id unknown, but prevent referencing a deleted parent already handled)
        resolved["parentTaskId"] = parent_task_row.get("id")

    # Create task
    now = _now()
    new_id = _gen_id("cu_tsk_")
    clickup_task_id = _gen_id("86")  # mimic ClickUp-like id-ish; still stored as string
    # preserve customFields array verbatim and order
    cf_store = None
    if customFields is not None:
        cf_store = [{"id": it["id"], "value": it.get("value")} for it in customFields]

    # tags: store as tag names array verbatim
    tag_store = None
    if tags is not None:
        tag_store = [t for t in tags]

    new_row = {
        "id": new_id,
        "workspace_id": ws_id,
        "clickup_task_id": clickup_task_id,
        "custom_id": None,
        "list_entity_id": list_ent.get("id"),
        "parent_task_id": parent_task_row.get("id") if parent_task_row else None,
        "name": name.strip(),
        "description": description if isinstance(description, str) else (description if description is None else str(description)),
        "status_text": status if isinstance(status, str) else None,
        "priority": priority,
        "due_date": due_v,
        "start_date": start_v,
        "assignee_clickup_user_ids": assignees if assignees is not None else None,
        "custom_fields": cf_store,
        "tag_names": tag_store,
        "status": "active",
        "last_synced_at": None,
        "raw": {
            "created_via": "integration_mirror",
            "list_clickup_id": list_ent.get("clickup_id"),
            "requested": {
                "status": status,
                "priority": priority,
                "dueDate": due_v,
                "startDate": start_v,
                "assignees": assignees,
                "tags": tags,
                "customFields": customFields,
                "parent": parent,
            },
        },
        "created_at": now,
        "updated_at": now,
    }
    tasks_rows.append(new_row)
    _save("tasks.json", tasks_rows)

    _op_write("succeeded", None, resolved=resolved or None)
    return {"task": new_row, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def get_task(workspaceId, taskId=None, taskName=None, listName=None, subtasks=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _oplog(workspace_id, tool_name, op_type, params, status, error_message=None, resolved=None):
        ops = _load("integration_operations.json")
        row = {
            "id": "op_" + uuid.uuid4().hex,
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "operation_type": op_type,
            "request_params": params,
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status,
            "error_message": error_message,
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        ops.append(row)
        _save("integration_operations.json", ops)
        return row

    params = {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "subtasks": subtasks}

    # Validate
    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
        _oplog(workspaceId if isinstance(workspaceId, str) else "unknown", "get_task", "read",
               params, "rejected", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")
        return _err("VALIDATION_ERROR", "workspaceId must match required format")
    if taskId is None and taskName is None:
        _oplog(workspaceId, "get_task", "read", params, "rejected", "Either taskId or taskName must be provided")
        return _err("VALIDATION_ERROR", "Either taskId or taskName must be provided")
    if taskId is not None and not isinstance(taskId, str):
        _oplog(workspaceId, "get_task", "read", params, "rejected", "taskId must be a string")
        return _err("VALIDATION_ERROR", "taskId must be a string")
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        _oplog(workspaceId, "get_task", "read", params, "rejected", "taskName must be a non-empty string")
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string")
    if listName is not None and not isinstance(listName, str):
        _oplog(workspaceId, "get_task", "read", params, "rejected", "listName must be a string")
        return _err("VALIDATION_ERROR", "listName must be a string")
    if subtasks is not None and not isinstance(subtasks, bool):
        _oplog(workspaceId, "get_task", "read", params, "rejected", "subtasks must be boolean")
        return _err("VALIDATION_ERROR", "subtasks must be a boolean")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws:
        _oplog(workspaceId, "get_task", "read", params, "failed", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")

    tasks = _load("tasks.json")
    ents = _load("hierarchy_entities.json")

    resolved = {}
    task = None

    if taskId is not None:
        matches = [t for t in tasks if t.get("workspace_id") == workspaceId and t.get("status") == "active"
                   and (t.get("clickup_task_id") == taskId or t.get("custom_id") == taskId)]
        if len(matches) == 0:
            _oplog(workspaceId, "get_task", "read", params, "failed", "Task not found")
            return _err("NOT_FOUND", "Task not found")
        if len(matches) > 1:
            _oplog(workspaceId, "get_task", "read", params, "rejected", "Ambiguous taskId/customId")
            return _err("CONFLICT", "Ambiguous task identifier")
        task = matches[0]
        resolved["taskIdentifier"] = taskId
        resolved["clickupTaskId"] = task.get("clickup_task_id")
    else:
        # Resolve by name, optionally narrow by listName
        list_entity_ids = None
        if listName is not None:
            list_candidates = [e for e in ents if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list"
                               and e.get("status") == "active" and e.get("name") == listName]
            if len(list_candidates) == 0:
                _oplog(workspaceId, "get_task", "read", params, "failed", "List not found by listName")
                return _err("NOT_FOUND", "List not found")
            if len(list_candidates) > 1:
                _oplog(workspaceId, "get_task", "read", params, "rejected", "Ambiguous listName; provide listId in other endpoints",
                       resolved={"listName": listName, "matches": [c.get("clickup_id") for c in list_candidates]})
                return _err("CONFLICT", "Ambiguous listName; cannot resolve taskName uniquely")
            list_entity_ids = {list_candidates[0].get("id")}
            resolved["listName"] = listName
            resolved["listClickupId"] = list_candidates[0].get("clickup_id")

        candidates = [t for t in tasks if t.get("workspace_id") == workspaceId and t.get("status") == "active"
                      and t.get("name") == taskName and (list_entity_ids is None or t.get("list_entity_id") in list_entity_ids)]
        if len(candidates) == 0:
            _oplog(workspaceId, "get_task", "read", params, "failed", "Task not found by name", resolved=resolved)
            return _err("NOT_FOUND", "Task not found")
        if len(candidates) > 1:
            _oplog(workspaceId, "get_task", "read", params, "rejected", "Multiple tasks match taskName; use taskId",
                   resolved={**resolved, "taskName": taskName, "matchCount": len(candidates)})
            return _err("CONFLICT", "Multiple tasks match taskName; use taskId")
        task = candidates[0]
        resolved["taskName"] = taskName
        resolved["clickupTaskId"] = task.get("clickup_task_id")

    include_sub = bool(subtasks) if subtasks is not None else False
    result = {"task": task}

    if include_sub:
        # Subtasks: tasks whose parent_task_id references this task's internal id
        parent_internal_id = task.get("id")
        subs = [t for t in tasks if t.get("workspace_id") == workspaceId and t.get("status") == "active"
                and t.get("parent_task_id") == parent_internal_id]
        result["subtasks"] = subs

    _oplog(workspaceId, "get_task", "read", params, "succeeded", None, resolved=resolved)
    result["latency_ms"] = int((time.time() - t0) * 1000)
    return result

def update_task(workspaceId, taskId=None, taskName=None, listName=None, name=None, description=None, status=None, priority=None, dueDate=None, startDate=None, assignees=None, tags=None, customFields=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _oplog(workspace_id, tool_name, op_type, params, status_s, error_message=None, resolved=None):
        ops = _load("integration_operations.json")
        row = {
            "id": "op_" + uuid.uuid4().hex,
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "operation_type": op_type,
            "request_params": params,
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_s,
            "error_message": error_message,
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now,
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        ops.append(row)
        _save("integration_operations.json", ops)
        return row

    params = {
        "workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName,
        "name": name, "description": description, "status": status, "priority": priority,
        "dueDate": dueDate, "startDate": startDate, "assignees": assignees, "tags": tags,
        "customFields": customFields
    }

    # Validate
    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
        _oplog(workspaceId if isinstance(workspaceId, str) else "unknown", "update_task", "write",
               params, "rejected", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")
        return _err("VALIDATION_ERROR", "workspaceId must match required format")
    if taskId is None and taskName is None:
        _oplog(workspaceId, "update_task", "write", params, "rejected", "Either taskId or taskName must be provided")
        return _err("VALIDATION_ERROR", "Either taskId or taskName must be provided")
    if taskId is not None and not isinstance(taskId, str):
        _oplog(workspaceId, "update_task", "write", params, "rejected", "taskId must be a string")
        return _err("VALIDATION_ERROR", "taskId must be a string")
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        _oplog(workspaceId, "update_task", "write", params, "rejected", "taskName must be a non-empty string")
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string")
    if listName is not None and not isinstance(listName, str):
        _oplog(workspaceId, "update_task", "write", params, "rejected", "listName must be a string")
        return _err("VALIDATION_ERROR", "listName must be a string")

    # At least one mutable field
    mutable_provided = any(v is not None for v in [name, description, status, priority, dueDate, startDate, assignees, tags, customFields])
    if not mutable_provided:
        _oplog(workspaceId, "update_task", "write", params, "rejected", "No updatable fields provided")
        return _err("VALIDATION_ERROR", "No updatable fields provided")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _oplog(workspaceId, "update_task", "write", params, "rejected", "name must be a non-empty string")
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if description is not None and not isinstance(description, str):
        _oplog(workspaceId, "update_task", "write", params, "rejected", "description must be a string")
        return _err("VALIDATION_ERROR", "description must be a string")
    if status is not None and not isinstance(status, str):
        _oplog(workspaceId, "update_task", "write", params, "rejected", "status must be a string")
        return _err("VALIDATION_ERROR", "status must be a string")
    if priority is not None:
        if not isinstance(priority, int):
            _oplog(workspaceId, "update_task", "write", params, "rejected", "priority must be an integer")
            return _err("VALIDATION_ERROR", "priority must be an integer")
        if priority < 1 or priority > 5:
            _oplog(workspaceId, "update_task", "write", params, "rejected", "priority must be between 1 and 5")
            return _err("VALIDATION_ERROR", "priority must be between 1 and 5")
    if assignees is not None:
        if not isinstance(assignees, list) or any(not isinstance(x, str) for x in assignees):
            _oplog(workspaceId, "update_task", "write", params, "rejected", "assignees must be an array of strings")
            return _err("VALIDATION_ERROR", "assignees must be an array of strings")
    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) or not x.strip() for x in tags):
            _oplog(workspaceId, "update_task", "write", params, "rejected", "tags must be an array of non-empty strings")
            return _err("VALIDATION_ERROR", "tags must be an array of non-empty strings")
    if customFields is not None:
        if not isinstance(customFields, list):
            _oplog(workspaceId, "update_task", "write", params, "rejected", "customFields must be an array")
            return _err("VALIDATION_ERROR", "customFields must be an array")
        for i, it in enumerate(customFields):
            if not isinstance(it, dict) or "id" not in it or "value" not in it or len(it.keys() - {"id", "value"}) != 0:
                _oplog(workspaceId, "update_task", "write", params, "rejected",
                       f"customFields[{i}] must be an object with only id and value")
                return _err("VALIDATION_ERROR", f"customFields[{i}] must include id and value")
            if not isinstance(it.get("id"), str) or not it["id"]:
                _oplog(workspaceId, "update_task", "write", params, "rejected", f"customFields[{i}].id must be a string")
                return _err("VALIDATION_ERROR", f"customFields[{i}].id must be a string")

    def _parse_iso(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO 8601 string")
        try:
            if s.endswith("Z"):
                datetime.datetime.fromisoformat(s[:-1])
            else:
                datetime.datetime.fromisoformat(s)
            return s
        except ValueError:
            raise ValueError(f"{field} must be an ISO 8601 date-time string")

    try:
        due_iso = _parse_iso(dueDate, "dueDate")
        start_iso = _parse_iso(startDate, "startDate")
    except ValueError as ve:
        _oplog(workspaceId, "update_task", "write", params, "rejected", str(ve))
        return _err("VALIDATION_ERROR", str(ve))

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws:
        _oplog(workspaceId, "update_task", "write", params, "failed", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")

    if ws.get("status") == "disabled":
        _oplog(workspaceId, "update_task", "write", params, "rejected", "Workspace is disabled")
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations")
    if ws.get("status") == "read_only":
        _oplog(workspaceId, "update_task", "write", params, "rejected", "Workspace is read-only")
        return _err("UNAUTHORIZED", "Workspace is read-only for write operations")

    tasks = _load("tasks.json")
    ents = _load("hierarchy_entities.json")

    resolved = {}
    task_idx = None
    task = None

    if taskId is not None:
        matches = [(i, t) for i, t in enumerate(tasks) if t.get("workspace_id") == workspaceId and t.get("status") == "active"
                   and (t.get("clickup_task_id") == taskId or t.get("custom_id") == taskId)]
        if len(matches) == 0:
            _oplog(workspaceId, "update_task", "write", params, "failed", "Task not found")
            return _err("NOT_FOUND", "Task not found")
        if len(matches) > 1:
            _oplog(workspaceId, "update_task", "write", params, "rejected", "Ambiguous task identifier")
            return _err("CONFLICT", "Ambiguous task identifier")
        task_idx, task = matches[0]
        resolved["taskIdentifier"] = taskId
        resolved["clickupTaskId"] = task.get("clickup_task_id")
    else:
        # resolve by name with optional listName narrowing
        list_entity_ids = None
        if listName is not None:
            list_candidates = [e for e in ents if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list"
                               and e.get("status") == "active" and e.get("name") == listName]
            if len(list_candidates) == 0:
                _oplog(workspaceId, "update_task", "write", params, "failed", "List not found")
                return _err("NOT_FOUND", "List not found")
            if len(list_candidates) > 1:
                _oplog(workspaceId, "update_task", "write", params, "rejected", "Ambiguous listName for taskName resolution")
                return _err("CONFLICT", "Ambiguous listName; cannot resolve taskName uniquely")
            list_entity_ids = {list_candidates[0].get("id")}
            resolved["listName"] = listName
            resolved["listClickupId"] = list_candidates[0].get("clickup_id")

        candidates = [(i, t) for i, t in enumerate(tasks)
                      if t.get("workspace_id") == workspaceId and t.get("status") == "active"
                      and t.get("name") == taskName and (list_entity_ids is None or t.get("list_entity_id") in list_entity_ids)]
        if len(candidates) == 0:
            _oplog(workspaceId, "update_task", "write", params, "failed", "Task not found by name", resolved=resolved)
            return _err("NOT_FOUND", "Task not found")
        if len(candidates) > 1:
            _oplog(workspaceId, "update_task", "write", params, "rejected", "Multiple tasks match taskName; specify taskId",
                   resolved={**resolved, "taskName": taskName, "matchCount": len(candidates)})
            return _err("CONFLICT", "Multiple tasks match taskName; specify taskId")
        task_idx, task = candidates[0]
        resolved["taskName"] = taskName
        resolved["clickupTaskId"] = task.get("clickup_task_id")

    # Apply updates (only provided fields)
    changed = False

    if name is not None:
        task["name"] = name
        changed = True
    if description is not None:
        task["description"] = description
        changed = True
    if status is not None:
        task["status_text"] = status
        changed = True
        if not isinstance(task.get("raw"), dict):
            task["raw"] = {}
        task["raw"]["status_text"] = status
    if priority is not None:
        task["priority"] = priority
        changed = True
    if dueDate is not None:
        task["due_date"] = due_iso
        changed = True
    if startDate is not None:
        task["start_date"] = start_iso
        changed = True
    if assignees is not None:
        task["assignee_clickup_user_ids"] = assignees
        changed = True
    if tags is not None:
        task["tag_names"] = tags
        changed = True

    # Custom fields upsert/replace-by-id (consistent rule: upsert per id)
    if customFields is not None:
        existing = task.get("custom_fields")
        if existing is None:
            existing = []
        if not isinstance(existing, list):
            existing = []
        by_id = {}
        # keep stable order: start from existing, update matching, append new in provided order
        order = []
        for it in existing:
            if isinstance(it, dict) and isinstance(it.get("id"), str):
                cid = it["id"]
                if cid not in by_id:
                    by_id[cid] = {"id": cid, "value": it.get("value")}
                    order.append(cid)
        for it in customFields:
            cid = it["id"]
            if cid not in by_id:
                order.append(cid)
            by_id[cid] = {"id": cid, "value": it.get("value")}
        task["custom_fields"] = [by_id[cid] for cid in order]
        changed = True

    if not changed:
        # Shouldn't happen because we validated mutable_provided, but keep safe.
        _oplog(workspaceId, "update_task", "write", params, "rejected", "No effective changes provided", resolved=resolved)
        return _err("VALIDATION_ERROR", "No effective changes provided")

    task["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    task["last_synced_at"] = task["updated_at"]

    tasks[task_idx] = task
    _save("tasks.json", tasks)

    _oplog(workspaceId, "update_task", "write", params, "succeeded", None, resolved=resolved)

    return {
        "task": task,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def delete_task(workspaceId, taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")

    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "delete_task",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName},
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    if (taskId is None or (isinstance(taskId, str) and not taskId.strip())) and (taskName is None or (isinstance(taskName, str) and not taskName.strip())):
        _op_write("rejected", "Either taskId or taskName is required", resolved=None)
        return _err("VALIDATION_ERROR", "Either taskId or taskName is required", field="taskId")

    tasks_rows = _rows(_load("tasks.json"))
    target = None
    resolved = {}

    # Resolve by taskId (accept internal id, clickup_task_id, or custom_id)
    if taskId is not None and isinstance(taskId, str) and taskId.strip():
        tid = taskId.strip()
        for tr in tasks_rows:
            if not isinstance(tr, dict):
                continue
            if tr.get("workspace_id") != ws_id:
                continue
            if tr.get("id") == tid or tr.get("clickup_task_id") == tid or (tr.get("custom_id") and tr.get("custom_id") == tid):
                target = tr
                break
        resolved["taskId"] = tid

    # Resolve by name (optionally listName narrows; if multiple -> CONFLICT)
    if target is None:
        if not isinstance(taskName, str) or not taskName.strip():
            _op_write("failed", "Task not found", resolved=resolved or None)
            return _err("NOT_FOUND", "Task not found", field="taskId")
        tname = taskName.strip()
        candidates = [tr for tr in tasks_rows if isinstance(tr, dict) and tr.get("workspace_id") == ws_id and tr.get("status") != "deleted" and tr.get("name") == tname]
        if listName is not None and isinstance(listName, str) and listName.strip():
            lname = listName.strip()
            ents = _rows(_load("hierarchy_entities.json"))
            lists = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == lname]
            if len(lists) == 0:
                _op_write("failed", "List not found for listName", resolved={"taskName": tname, "listName": lname})
                return _err("NOT_FOUND", "List not found for listName", field="listName")
            if len(lists) > 1:
                _op_write("rejected", "listName is ambiguous; provide taskId or listId-scoped resolution", resolved={"taskName": tname, "listName": lname, "matchCount": len(lists)})
                return _err("CONFLICT", "listName is ambiguous; provide taskId", field="listName", matchCount=len(lists))
            list_entity_id = lists[0].get("id")
            candidates = [tr for tr in candidates if tr.get("list_entity_id") == list_entity_id]
            resolved.update({"taskName": tname, "listName": lname, "listEntityId": list_entity_id})
        else:
            resolved["taskName"] = tname

        if len(candidates) == 0:
            _op_write("failed", "Task not found", resolved=resolved or None)
            return _err("NOT_FOUND", "Task not found", field="taskName")
        if len(candidates) > 1:
            _op_write("rejected", "taskName is ambiguous; provide taskId or include listName", resolved={**resolved, "matchCount": len(candidates)})
            return _err("CONFLICT", "taskName is ambiguous; provide taskId or include listName", field="taskName", matchCount=len(candidates))
        target = candidates[0]

    # Enforce lifecycle transition: active -> deleted only
    if target.get("status") == "deleted":
        _op_write("succeeded", None, resolved={**resolved, "taskRowId": target.get("id")})
        return {"deleted": True, "task": target, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

    now = _now()
    target["status"] = "deleted"
    target["updated_at"] = now
    raw = target.get("raw") if isinstance(target.get("raw"), dict) else {}
    raw["deleted_via"] = "integration_mirror"
    raw["deleted_at"] = now
    target["raw"] = raw

    _save("tasks.json", tasks_rows)
    _op_write("succeeded", None, resolved={**resolved, "taskRowId": target.get("id")})
    return {"deleted": True, "task": target, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def get_task_comments(workspaceId, taskId=None, taskName=None, listName=None, start=None, startId=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_str(x):
        return isinstance(x, str)

    def _op_log(workspace_id, tool_name, operation_type, request_params, status, error_message=None, resolved_clickup_ids=None, bulk_count=None, succeeded_count=None, failed_count=None, started_at=None, finished_at=None):
        ops = _load("integration_operations.json")
        ts = _now()
        row = {
            "id": _new_id("op"),
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "operation_type": operation_type,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "resolved_clickup_ids": resolved_clickup_ids,
            "bulk_count": bulk_count,
            "succeeded_count": succeeded_count,
            "failed_count": failed_count,
            "status": status,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": ts,
            "updated_at": ts,
        }
        ops.append(row)
        _save("integration_operations.json", ops)
        return row

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        # Accept ISO-ish with trailing Z
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    t0 = time.time()
    started = _now()

    if not _is_str(workspaceId) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
        _op_log(workspaceId if _is_str(workspaceId) else "unknown", "get_task_comments", "read",
                {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                "rejected", "Invalid workspaceId format", started_at=started, finished_at=_now())
        return _err("VALIDATION_ERROR", "Invalid workspaceId format")

    for k, v in [("taskId", taskId), ("taskName", taskName), ("listName", listName), ("startId", startId)]:
        if v is not None and not _is_str(v):
            _op_log(workspaceId, "get_task_comments", "read",
                    {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                    "rejected", f"{k} must be a string", started_at=started, finished_at=_now())
            return _err("VALIDATION_ERROR", f"{k} must be a string")

    if start is not None and not isinstance(start, int):
        _op_log(workspaceId, "get_task_comments", "read",
                {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                "rejected", "start must be an integer", started_at=started, finished_at=_now())
        return _err("VALIDATION_ERROR", "start must be an integer")
    if isinstance(start, int) and start < 0:
        _op_log(workspaceId, "get_task_comments", "read",
                {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                "rejected", "start must be >= 0", started_at=started, finished_at=_now())
        return _err("VALIDATION_ERROR", "start must be >= 0")

    if (taskId is None or taskId.strip() == "") and (taskName is None or taskName.strip() == ""):
        _op_log(workspaceId, "get_task_comments", "read",
                {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                "rejected", "Either taskId or taskName is required", started_at=started, finished_at=_now())
        return _err("VALIDATION_ERROR", "Either taskId or taskName is required")

    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not wsp:
        _op_log(workspaceId, "get_task_comments", "read",
                {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                "failed", "Workspace not found", started_at=started, finished_at=_now())
        return _err("NOT_FOUND", "Workspace not found")

    if wsp.get("status") == "disabled":
        _op_log(workspaceId, "get_task_comments", "read",
                {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                "rejected", "Workspace disabled", started_at=started, finished_at=_now())
        return _err("UNAUTHORIZED", "Workspace is disabled", workspace_status=wsp.get("status"))

    tasks = _load("tasks.json")
    entities = _load("hierarchy_entities.json")
    activity = _load("task_activity.json")

    resolved = {}

    # Resolve task
    task = None
    if taskId is not None and taskId.strip() != "":
        tid = taskId.strip()
        task = next((t for t in tasks
                     if t.get("workspace_id") == workspaceId
                     and t.get("status") == "active"
                     and (t.get("clickup_task_id") == tid or (t.get("custom_id") == tid and t.get("custom_id") is not None))), None)
        if not task:
            _op_log(workspaceId, "get_task_comments", "read",
                    {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                    "failed", "Task not found", started_at=started, finished_at=_now(),
                    resolved_clickup_ids={"taskLookup": tid})
            return _err("NOT_FOUND", "Task not found")
        resolved["taskClickupId"] = task.get("clickup_task_id")
    else:
        name = taskName.strip()
        candidates = [t for t in tasks
                      if t.get("workspace_id") == workspaceId
                      and t.get("status") == "active"
                      and t.get("name") == name]
        if listName is not None and listName.strip() != "":
            list_candidates = [e for e in entities
                               if e.get("workspace_id") == workspaceId
                               and e.get("entity_type") == "list"
                               and e.get("status") == "active"
                               and e.get("name") == listName.strip()]
            if len(list_candidates) == 0:
                _op_log(workspaceId, "get_task_comments", "read",
                        {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                        "failed", "listName not found", started_at=started, finished_at=_now())
                return _err("NOT_FOUND", "listName not found")
            if len(list_candidates) > 1:
                _op_log(workspaceId, "get_task_comments", "read",
                        {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                        "rejected", "Ambiguous listName; cannot narrow taskName uniquely", started_at=started, finished_at=_now(),
                        resolved_clickup_ids={"listName": listName.strip(), "matches": [c.get("clickup_id") for c in list_candidates]})
                return _err("CONFLICT", "Ambiguous listName; provide taskId", matches=[c.get("clickup_id") for c in list_candidates])
            target_list = list_candidates[0]
            candidates = [t for t in candidates if t.get("list_entity_id") == target_list.get("id")]
            resolved["sourceListClickupId"] = target_list.get("clickup_id")

        if len(candidates) == 0:
            _op_log(workspaceId, "get_task_comments", "read",
                    {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                    "failed", "Task not found for taskName", started_at=started, finished_at=_now(),
                    resolved_clickup_ids={**resolved, "taskName": name})
            return _err("NOT_FOUND", "Task not found for taskName")
        if len(candidates) > 1:
            _op_log(workspaceId, "get_task_comments", "read",
                    {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
                    "rejected", "taskName matched multiple tasks", started_at=started, finished_at=_now(),
                    resolved_clickup_ids={**resolved, "taskName": name, "matches": [c.get("clickup_task_id") for c in candidates]})
            return _err("CONFLICT", "taskName matched multiple tasks; provide taskId or narrow by listName", matches=[c.get("clickup_task_id") for c in candidates])
        task = candidates[0]
        resolved["taskClickupId"] = task.get("clickup_task_id")

    # Filter comments
    comments = [a for a in activity
                if a.get("workspace_id") == workspaceId
                and a.get("task_id") == task.get("id")
                and a.get("activity_type") == "comment"
                and a.get("status") == "active"]

    # Sort by occurred_at ascending (default)
    comments.sort(key=lambda r: (_parse_dt(r.get("occurred_at")) or datetime.datetime.min, r.get("id") or ""))

    # Apply startId cursor: start AFTER the row with cursor_id == startId
    if startId is not None and startId.strip() != "":
        sid = startId.strip()
        idx = None
        for i, r in enumerate(comments):
            if r.get("cursor_id") == sid:
                idx = i
                break
        if idx is not None:
            comments = comments[idx + 1:]
        # If startId not found, treat as starting from beginning (no error)

    # Apply start offset
    offset = start if isinstance(start, int) else 0
    if offset:
        comments = comments[offset:]

    # Page size: choose a reasonable default (ClickUp-like endpoints often default 100)
    page_size = 100
    page = comments[:page_size]
    has_more = len(comments) > page_size
    next_cursor = None
    if has_more and page:
        next_cursor = page[-1].get("cursor_id") or page[-1].get("id")

    finished = _now()
    _op_log(workspaceId, "get_task_comments", "read",
            {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "start": start, "startId": startId},
            "succeeded", None, resolved_clickup_ids=resolved, started_at=started, finished_at=finished)

    return {
        "task_id": task.get("id"),
        "comments": page,
        "pagination": {
            "start": offset,
            "startId": startId,
            "limit": page_size,
            "returned": len(page),
            "total_matching": len(comments),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }

def create_task_comment(workspaceId, commentText, taskId=None, taskName=None, listName=None, notifyAll=None, assignee=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")

    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "create_task_comment",
            "operation_type": "write",
            "request_params": {
                "workspaceId": workspaceId,
                "taskId": taskId,
                "taskName": taskName,
                "listName": listName,
                "commentText": commentText,
                "notifyAll": notifyAll,
                "assignee": assignee,
            },
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    if not isinstance(commentText, str) or not commentText.strip():
        _op_write("rejected", "commentText is required", resolved=None)
        return _err("VALIDATION_ERROR", "commentText is required", field="commentText")

    if notifyAll is not None and not isinstance(notifyAll, bool):
        _op_write("rejected", "notifyAll must be boolean", resolved=None)
        return _err("VALIDATION_ERROR", "notifyAll must be boolean", field="notifyAll")

    if assignee is not None and (not isinstance(assignee, str) or not assignee.strip()):
        _op_write("rejected", "assignee must be a non-empty string when provided", resolved=None)
        return _err("VALIDATION_ERROR", "assignee must be a non-empty string when provided", field="assignee")

    tasks_rows = _rows(_load("tasks.json"))
    target = None
    resolved = {}

    # Resolve task by internal id, clickup_task_id, custom_id; fallback to name (+listName recommended)
    if taskId is not None and isinstance(taskId, str) and taskId.strip():
        tid = taskId.strip()
        for tr in tasks_rows:
            if not isinstance(tr, dict):
                continue
            if tr.get("workspace_id") != ws_id:
                continue
            if tr.get("status") != "active":
                continue
            if tr.get("id") == tid or tr.get("clickup_task_id") == tid or (tr.get("custom_id") and tr.get("custom_id") == tid):
                target = tr
                break
        resolved["taskId"] = tid

    if target is None:
        if not isinstance(taskName, str) or not taskName.strip():
            _op_write("rejected", "Either taskId or taskName is required", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "Either taskId or taskName is required", field="taskId")
        tname = taskName.strip()
        candidates = [tr for tr in tasks_rows if isinstance(tr, dict) and tr.get("workspace_id") == ws_id and tr.get("status") == "active" and tr.get("name") == tname]
        resolved["taskName"] = tname
        if listName is not None and isinstance(listName, str) and listName.strip():
            lname = listName.strip()
            ents = _rows(_load("hierarchy_entities.json"))
            lists = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == lname]
            if len(lists) == 0:
                _op_write("failed", "List not found for listName", resolved={**resolved, "listName": lname})
                return _err("NOT_FOUND", "List not found for listName", field="listName")
            if len(lists) > 1:
                _op_write("rejected", "listName is ambiguous; provide taskId", resolved={**resolved, "listName": lname, "matchCount": len(lists)})
                return _err("CONFLICT", "listName is ambiguous; provide taskId", field="listName", matchCount=len(lists))
            list_entity_id = lists[0].get("id")
            candidates = [tr for tr in candidates if tr.get("list_entity_id") == list_entity_id]
            resolved.update({"listName": lname, "listEntityId": list_entity_id})

        if len(candidates) == 0:
            _op_write("failed", "Task not found", resolved=resolved or None)
            return _err("NOT_FOUND", "Task not found", field="taskName")
        if len(candidates) > 1:
            _op_write("rejected", "taskName is ambiguous; provide taskId or include listName", resolved={**resolved, "matchCount": len(candidates)})
            return _err("CONFLICT", "taskName is ambiguous; provide taskId or include listName", field="taskName", matchCount=len(candidates))
        target = candidates[0]

    # Insert activity row
    now = _now()
    activity_rows = _rows(_load("task_activity.json"))
    clickup_comment_id = _gen_id("cmt_")
    cursor_id = clickup_comment_id  # business rule

    new_act = {
        "id": _gen_id("cu_act_"),
        "workspace_id": ws_id,
        "task_id": target.get("id"),
        "activity_type": "comment",
        "clickup_comment_id": clickup_comment_id,
        "comment_text": commentText,
        "comment_assignee_clickup_user_id": assignee.strip() if isinstance(assignee, str) and assignee.strip() else None,
        "comment_notify_all": notifyAll if isinstance(notifyAll, bool) else None,
        "attachment_clickup_file_id": None,
        "attachment_filename": None,
        "attachment_source_type": None,
        "attachment_url": None,
        "tag_space_entity_id": None,
        "tag_name": None,
        "cursor_id": cursor_id,
        "occurred_at": now,
        "status": "active",
        "raw": {"created_via": "integration_mirror"},
        "created_at": now,
        "updated_at": now,
    }
    activity_rows.append(new_act)
    _save("task_activity.json", activity_rows)

    _op_write("succeeded", None, resolved={**resolved, "taskRowId": target.get("id"), "clickupCommentId": clickup_comment_id})
    return {"comment": new_act, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

