        if not isinstance(base64, str) or not base64.strip():
            _op_write("rejected", "base64 is required when sourceType=base64", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "base64 is required when sourceType=base64", field="base64")
        try:
            payload = b64mod.b64decode(base64, validate=True)
        except Exception:
            _op_write("rejected", "base64 payload is not valid base64", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "base64 payload is not valid base64", field="base64")
        if len(payload) > 10 * 1024 * 1024:
            _op_write("rejected", "base64 payload exceeds 10MB limit", resolved={**resolved, "sizeBytes": len(payload)})
            return _err("VALIDATION_ERROR", "base64 payload exceeds 10MB limit", field="base64", maxBytes=10 * 1024 * 1024)
        attach["sizeBytes"] = len(payload)

    elif sourceType == "url":
        if not isinstance(url, str) or not url.strip():
            _op_write("rejected", "url is required when sourceType=url", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "url is required when sourceType=url", field="url")
        u = url.strip()
        p = urllib.parse.urlparse(u)
        if p.scheme not in ("http", "https"):
            _op_write("rejected", "Only http/https URLs are allowed", resolved={**resolved, "url": u})
            return _err("VALIDATION_ERROR", "Only http/https URLs are allowed", field="url")
        attach["url"] = u

    elif sourceType == "local_path":
        if not isinstance(localPath, str) or not localPath.strip():
            _op_write("rejected", "localPath is required when sourceType=local_path", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "localPath is required when sourceType=local_path", field="localPath")
        lp = localPath.strip()
        if not os.path.isabs(lp):
            _op_write("rejected", "localPath must be an absolute path", resolved={**resolved, "localPath": lp})
            return _err("VALIDATION_ERROR", "localPath must be an absolute path", field="localPath")
        if not os.path.exists(lp) or not os.path.isfile(lp):
            _op_write("failed", "localPath does not exist or is not a file", resolved={**resolved, "localPath": lp})
            return _err("NOT_FOUND", "localPath does not exist or is not a file", field="localPath")
        try:
            with open(lp, "rb") as f:
                data = f.read(1024 * 1024 + 1)  # just test readability; no need to load full file
        except Exception:
            _op_write("failed", "localPath is not readable by the server", resolved={**resolved, "localPath": lp})
            return _err("UNAUTHORIZED", "localPath is not readable by the server", field="localPath")
        attach["localPath"] = lp
        attach["readable"] = True
        attach["sampleBytesRead"] = len(data)

    elif sourceType == "chunked":
        if not isinstance(chunked, dict) or not isinstance(chunked.get("uploadId"), str) or not chunked.get("uploadId").strip():
            _op_write("rejected", "chunked.uploadId is required when sourceType=chunked", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "chunked.uploadId is required when sourceType=chunked", field="chunked.uploadId")
        if "totalBytes" in chunked and chunked["totalBytes"] is not None:
            if not isinstance(chunked["totalBytes"], int) or chunked["totalBytes"] < 1:
                _op_write("rejected", "chunked.totalBytes must be an integer >= 1 when provided", resolved=resolved or None)
                return _err("VALIDATION_ERROR", "chunked.totalBytes must be an integer >= 1 when provided", field="chunked.totalBytes")
        attach["chunked"] = {"uploadId": chunked.get("uploadId").strip(), "totalBytes": chunked.get("totalBytes")}

    # Insert activity row
    now = _now()
    activity_rows = _rows(_load("task_activity.json"))
    file_id = _gen_id("file_")
    new_act = {
        "id": _gen_id("cu_act_"),
        "workspace_id": ws_id,
        "task_id": target.get("id"),
        "activity_type": "attachment",
        "clickup_comment_id": None,
        "comment_text": None,
        "comment_assignee_clickup_user_id": None,
        "comment_notify_all": None,
        "attachment_clickup_file_id": file_id,
        "attachment_filename": filename.strip() if isinstance(filename, str) and filename.strip() else None,
        "attachment_source_type": sourceType,
        "attachment_url": attach.get("url"),
        "tag_space_entity_id": None,
        "tag_name": None,
        "cursor_id": None,
        "occurred_at": now,
        "status": "active",
        "raw": {"created_via": "integration_mirror", "attachment": attach},
        "created_at": now,
        "updated_at": now,
    }
    activity_rows.append(new_act)
    _save("task_activity.json", activity_rows)

    _op_write("succeeded", None, resolved={**resolved, "taskRowId": target.get("id"), "attachmentClickupFileId": file_id})
    return {"attachment": new_act, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def create_bulk_tasks(workspaceId, tasks, listId=None, listName=None, options=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []
    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()
    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 string", field=field)
        v = s.strip()
        try:
            datetime.datetime.fromisoformat(v[:-1] if v.endswith("Z") else v)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be ISO 8601 date-time", field=field)
        return v, None

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")
    if not isinstance(tasks, list) or len(tasks) < 1:
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array", field="tasks")

    bulk_count = len(tasks)

    # Resolve workspace
    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None, succeeded_count=None, failed_count=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "create_bulk_tasks",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "tasks": tasks, "options": options},
            "resolved_clickup_ids": resolved,
            "bulk_count": bulk_count,
            "succeeded_count": succeeded_count,
            "failed_count": failed_count,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None, succeeded_count=0, failed_count=bulk_count)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None, succeeded_count=0, failed_count=bulk_count)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    # Resolve list
    ents = _rows(_load("hierarchy_entities.json"))
    resolved = {}
    list_ent = None

    if listId is not None and isinstance(listId, str) and listId.strip():
        lid = listId.strip()
        for e in ents:
            if not isinstance(e, dict):
                continue
            if e.get("workspace_id") != ws_id or e.get("entity_type") != "list" or e.get("status") != "active":
                continue
            if e.get("id") == lid or e.get("clickup_id") == lid:
                list_ent = e
                break
        resolved["listId"] = lid

    if list_ent is None:
        if not isinstance(listName, str) or not listName.strip():
            _op_write("rejected", "Either listId or listName is required", resolved=resolved or None, succeeded_count=0, failed_count=bulk_count)
            return _err("VALIDATION_ERROR", "Either listId or listName is required", field="listId")
        lname = listName.strip()
        matches = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == lname]
        if len(matches) == 0:
            _op_write("failed", "Destination list not found", resolved={"listName": lname}, succeeded_count=0, failed_count=bulk_count)
            return _err("NOT_FOUND", "Destination list not found", field="listName")
        if len(matches) > 1:
            _op_write("rejected", "listName is ambiguous; provide listId", resolved={"listName": lname, "matchCount": len(matches)}, succeeded_count=0, failed_count=bulk_count)
            return _err("CONFLICT", "listName is ambiguous; provide listId", field="listName", matchCount=len(matches))
        list_ent = matches[0]
        resolved["listName"] = lname

    resolved.update({"listEntityId": list_ent.get("id"), "listClickupId": list_ent.get("clickup_id")})

    # Validate tasks array items and create
    tasks_rows = _rows(_load("tasks.json"))
    created = []
    failures = []

    for idx, it in enumerate(tasks):
        if not isinstance(it, dict):
            failures.append({"index": idx, "error": "task item must be an object"})
            continue
        nm = it.get("name")
        if not isinstance(nm, str) or not nm.strip():
            failures.append({"index": idx, "error": "name is required"})
            continue

        pr = it.get("priority")
        if pr is not None:
            if not isinstance(pr, int) or pr < 1 or pr > 5:
                failures.append({"index": idx, "error": "priority must be integer between 1 and 5"})
                continue

        dd, dde = _parse_dt(it.get("dueDate"), f"tasks[{idx}].dueDate")
        if dde:
            failures.append({"index": idx, "error": dde["error"]["message"], "field": dde["error"].get("field")})
            continue
        sd, sde = _parse_dt(it.get("startDate"), f"tasks[{idx}].startDate")
        if sde:
            failures.append({"index": idx, "error": sde["error"]["message"], "field": sde["error"].get("field")})
            continue

        asg = it.get("assigneeClickupUserIds")
        if asg is not None and not (isinstance(asg, list) and all(isinstance(x, str) for x in asg)):
            failures.append({"index": idx, "error": "assigneeClickupUserIds must be an array of strings"})
            continue

        tgn = it.get("tagNames")
        if tgn is not None and not (isinstance(tgn, list) and all(isinstance(x, str) for x in tgn)):
            failures.append({"index": idx, "error": "tagNames must be an array of strings"})
            continue

        cfs = it.get("customFields")
        if cfs is not None:
            if not isinstance(cfs, list):
                failures.append({"index": idx, "error": "customFields must be an array of {id,value}"})
                continue
            bad = False
            for cf in cfs:
                if not isinstance(cf, dict) or "id" not in cf or "value" not in cf or not isinstance(cf.get("id"), str) or not cf.get("id").strip():
                    bad = True
                    break
            if bad:
                failures.append({"index": idx, "error": "customFields items must include non-empty id and value"})
                continue

        now = _now()
        new_row = {
            "id": _gen_id("cu_tsk_"),
            "workspace_id": ws_id,
            "clickup_task_id": _gen_id("86"),
            "custom_id": None,
            "list_entity_id": list_ent.get("id"),
            "parent_task_id": None,
            "name": nm.strip(),
            "description": it.get("description") if isinstance(it.get("description"), str) else (it.get("description") if it.get("description") is None else str(it.get("description"))),
            "status_text": it.get("statusText") if isinstance(it.get("statusText"), str) else None,
            "priority": pr,
            "due_date": dd,
            "start_date": sd,
            "assignee_clickup_user_ids": asg if asg is not None else None,
            "custom_fields": ([{"id": cf["id"], "value": cf.get("value")} for cf in cfs] if cfs is not None else None),
            "tag_names": ([x for x in tgn] if tgn is not None else None),
            "status": "active",
            "last_synced_at": None,
            "raw": {"created_via": "integration_mirror", "list_clickup_id": list_ent.get("clickup_id")},
            "created_at": now,
            "updated_at": now,
        }
        tasks_rows.append(new_row)
        created.append(new_row)

    if created:
        _save("tasks.json", tasks_rows)

    succeeded_count = len(created)
    failed_count = len(failures)
    if succeeded_count == 0:
        _op_write("failed", "No tasks created", resolved=resolved or None, succeeded_count=0, failed_count=failed_count)
        return _err("VALIDATION_ERROR", "No tasks created; all items failed validation", failures=failures)

    # If partial failures, mark operation failed? We'll mark succeeded but include failures; ClickUp bulk often partial-success.
    op_status = "succeeded" if failed_count == 0 else "failed"
    _op_write(op_status, None if failed_count == 0 else "Some tasks failed validation", resolved=resolved or None, succeeded_count=succeeded_count, failed_count=failed_count)
    return {
        "tasks": created,
        "failures": failures,
        "counts": {"requested": bulk_count, "succeeded": succeeded_count, "failed": failed_count},
        "operation_id": op_id,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def update_bulk_tasks(workspaceId, tasks, options=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ops = _load("integration_operations.json")
    workspaces = _load("workspaces.json")
    hierarchy = _load("hierarchy_entities.json")
    task_rows = _load("tasks.json")

    def _new_id(prefix):
        return f"{prefix}{uuid.uuid4().hex[:12].upper()}"

    def _log_and_return(op_row, resp):
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        ops.append(op_row)
        _save("integration_operations.json", ops)
        return resp

    op = {
        "id": _new_id("cu_op_"),
        "workspace_id": workspaceId,
        "tool_name": "update_bulk_tasks",
        "operation_type": "write",
        "request_params": {
            "workspaceId": workspaceId,
            "tasks": tasks,
            "options": options,
        },
        "resolved_clickup_ids": None,
        "bulk_count": (len(tasks) if isinstance(tasks, list) else None),
        "succeeded_count": 0,
        "failed_count": 0,
        "status": "received",
        "error_message": None,
        "started_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Validate basic inputs
    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{3,}$", workspaceId):
        op["status"] = "rejected"
        op["error_message"] = "workspaceId must match ^cu_wsp_[0-9A-Z]{3,}$"
        return _log_and_return(op, _err("VALIDATION_ERROR", op["error_message"], field="workspaceId"))
    if not isinstance(tasks, list) or len(tasks) < 1:
        op["status"] = "rejected"
        op["error_message"] = "tasks must be a non-empty array"
        return _log_and_return(op, _err("VALIDATION_ERROR", op["error_message"], field="tasks"))
    if options is not None and not isinstance(options, dict):
        op["status"] = "rejected"
        op["error_message"] = "options must be an object"
        return _log_and_return(op, _err("VALIDATION_ERROR", op["error_message"], field="options"))
    if isinstance(options, dict):
        if "batchSize" in options and (not isinstance(options["batchSize"], int) or options["batchSize"] < 1):
            op["status"] = "rejected"
            op["error_message"] = "options.batchSize must be an integer >= 1"
            return _log_and_return(op, _err("VALIDATION_ERROR", op["error_message"], field="options.batchSize"))
        if "concurrency" in options and (not isinstance(options["concurrency"], int) or options["concurrency"] < 1):
            op["status"] = "rejected"
            op["error_message"] = "options.concurrency must be an integer >= 1"
            return _log_and_return(op, _err("VALIDATION_ERROR", op["error_message"], field="options.concurrency"))

    wsp = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not wsp:
        op["status"] = "failed"
        op["error_message"] = "Workspace not found"
        return _log_and_return(op, _err("NOT_FOUND", op["error_message"], workspaceId=workspaceId))
    if wsp.get("status") == "disabled":
        op["status"] = "rejected"
        op["error_message"] = "Workspace is disabled; write operations are not allowed"
        return _log_and_return(op, _err("UNAUTHORIZED", op["error_message"], workspaceId=workspaceId))
    if wsp.get("status") == "read_only":
        op["status"] = "rejected"
        op["error_message"] = "Workspace is read_only; write operations are not allowed"
        return _log_and_return(op, _err("UNAUTHORIZED", op["error_message"], workspaceId=workspaceId))

    # Helpers
    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__ERR__", f"{field} must be an ISO 8601 date-time string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                datetime.datetime.fromisoformat(ss.replace("Z", "+00:00"))
                return ss
            datetime.datetime.fromisoformat(ss)
            return ss
        except Exception:
            return ("__ERR__", f"{field} must be a valid ISO 8601 date-time string")

    # Indexes for fast lookup
    by_id = {t.get("id"): t for t in task_rows if isinstance(t, dict)}
    lists_by_name = {}
    for e in hierarchy:
        if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list" and e.get("status") == "active":
            lists_by_name.setdefault(e.get("name"), []).append(e)

    resolved_any = []
    updated = []
    failures = []

    # Custom fields upsert/replace policy: upsert by id (consistent).
    def _upsert_custom_fields(existing, incoming):
        if incoming is None:
            return existing
        # validate incoming elsewhere
        ex = existing if isinstance(existing, list) else []
        ex_map = {}
        for cf in ex:
            if isinstance(cf, dict) and isinstance(cf.get("id"), str):
                ex_map[cf["id"]] = cf.get("value")
        for cf in incoming:
            ex_map[cf["id"]] = cf.get("value")
        # stable order: existing order then new ids in incoming order
        out = []
        seen = set()
        for cf in ex:
            if isinstance(cf, dict) and isinstance(cf.get("id"), str) and cf["id"] in ex_map and cf["id"] not in seen:
                out.append({"id": cf["id"], "value": ex_map[cf["id"]]})
                seen.add(cf["id"])
        for cf in incoming:
            if cf["id"] not in seen:
                out.append({"id": cf["id"], "value": ex_map[cf["id"]]})
                seen.add(cf["id"])
        return out

    for idx, item in enumerate(tasks):
        if not isinstance(item, dict):
            failures.append({"index": idx, "error": "Task update item must be an object"})
            continue

        upd = item.get("update")
        if not isinstance(upd, dict) or len(upd.keys()) == 0:
            failures.append({"index": idx, "error": "update must be an object with at least one field"})
            continue

        # Identify task: taskId preferred; else taskName + listName required (per rules)
        target = None
        res = {"index": idx}
        taskId = item.get("taskId")
        taskName = item.get("taskName")
        listName = item.get("listName")

        if taskId is not None:
            if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]{3,}$", taskId):
                failures.append({"index": idx, "error": "taskId must match ^cu_tsk_[0-9A-Z]{3,}$"})
                continue
            target = by_id.get(taskId)
            if not target or target.get("workspace_id") != workspaceId or target.get("status") != "active":
                failures.append({"index": idx, "error": "Task not found", "taskId": taskId})
                continue
            res["taskId"] = taskId
            res["clickupTaskId"] = target.get("clickup_task_id")
        else:
            # Must have listName for taskName resolution in bulk
            if taskName is None or not isinstance(taskName, str) or not taskName.strip():
                failures.append({"index": idx, "error": "Either taskId or taskName must be provided"})
                continue
            if listName is None or not isinstance(listName, str) or not listName.strip():
                # explicit rule: must be scoped to list; reject and log rejected.
                failures.append({"index": idx, "error": "listName is required when identifying by taskName"})
                continue

            list_matches = lists_by_name.get(listName, [])
            if len(list_matches) == 0:
                failures.append({"index": idx, "error": "List not found", "listName": listName})
                continue
            if len(list_matches) > 1:
                failures.append({"index": idx, "error": "Ambiguous listName; multiple active lists match", "listName": listName, "matches": len(list_matches)})
                continue
            list_ent = list_matches[0]
            candidates = [t for t in task_rows
                          if t.get("workspace_id") == workspaceId and t.get("status") == "active"
                          and t.get("list_entity_id") == list_ent.get("id") and t.get("name") == taskName]
            if len(candidates) == 0:
                failures.append({"index": idx, "error": "taskName resolution yielded 0 candidates", "taskName": taskName, "listName": listName})
                continue
            if len(candidates) > 1:
                failures.append({"index": idx, "error": "taskName resolution yielded multiple candidates", "taskName": taskName, "listName": listName, "matches": len(candidates)})
                continue
            target = candidates[0]
            res["taskName"] = taskName
            res["listName"] = listName
            res["taskId"] = target.get("id")
            res["clickupTaskId"] = target.get("clickup_task_id")

        # Validate update fields
        if "priority" in upd and upd["priority"] is not None:
            if not isinstance(upd["priority"], int) or upd["priority"] < 1 or upd["priority"] > 5:
                failures.append({"index": idx, "error": "priority must be an integer between 1 and 5", "taskId": res.get("taskId")})
                continue
        if "assigneeClickupUserIds" in upd and upd["assigneeClickupUserIds"] is not None:
            a = upd["assigneeClickupUserIds"]
            if not isinstance(a, list) or any(not isinstance(x, str) for x in a):
                failures.append({"index": idx, "error": "assigneeClickupUserIds must be an array of strings", "taskId": res.get("taskId")})
                continue
        if "tagNames" in upd and upd["tagNames"] is not None:
            tg = upd["tagNames"]
            if not isinstance(tg, list) or any(not isinstance(x, str) for x in tg):
                failures.append({"index": idx, "error": "tagNames must be an array of strings", "taskId": res.get("taskId")})
                continue
        if "customFields" in upd and upd["customFields"] is not None:
            cf = upd["customFields"]
            if not isinstance(cf, list):
                failures.append({"index": idx, "error": "customFields must be an array", "taskId": res.get("taskId")})
                continue
            ok = True
            for c in cf:
                if not isinstance(c, dict) or "id" not in c or "value" not in c or not isinstance(c.get("id"), str):
                    ok = False
                    break
            if not ok:
                failures.append({"index": idx, "error": "customFields items must be objects with string id and value", "taskId": res.get("taskId")})
                continue
        if "dueDate" in upd:
            parsed = _parse_dt(upd.get("dueDate"), "dueDate")
            if isinstance(parsed, tuple) and parsed[0] == "__ERR__":
                failures.append({"index": idx, "error": parsed[1], "taskId": res.get("taskId")})
                continue
        if "startDate" in upd:
            parsed = _parse_dt(upd.get("startDate"), "startDate")
            if isinstance(parsed, tuple) and parsed[0] == "__ERR__":
                failures.append({"index": idx, "error": parsed[1], "taskId": res.get("taskId")})
                continue

        # Apply updates (only provided fields)
        changed = False
        if "name" in upd:
            if upd["name"] is not None and (not isinstance(upd["name"], str) or not upd["name"].strip()):
                failures.append({"index": idx, "error": "name must be a non-empty string when provided", "taskId": res.get("taskId")})
                continue
            target["name"] = upd["name"]
            changed = True
        if "description" in upd:
            # allow null to clear
            if upd["description"] is not None and not isinstance(upd["description"], str):
                failures.append({"index": idx, "error": "description must be a string or null", "taskId": res.get("taskId")})
                continue
            target["description"] = upd["description"]
            changed = True
        if "statusText" in upd:
            if upd["statusText"] is not None and not isinstance(upd["statusText"], str):
                failures.append({"index": idx, "error": "statusText must be a string or null", "taskId": res.get("taskId")})
                continue
            target["status_text"] = upd["statusText"]
            changed = True
        if "priority" in upd:
            target["priority"] = upd.get("priority")
            changed = True
        if "dueDate" in upd:
            target["due_date"] = _parse_dt(upd.get("dueDate"), "dueDate") if upd.get("dueDate") is not None else None
            changed = True
        if "startDate" in upd:
            target["start_date"] = _parse_dt(upd.get("startDate"), "startDate") if upd.get("startDate") is not None else None
            changed = True
        if "assigneeClickupUserIds" in upd:
            target["assignee_clickup_user_ids"] = upd.get("assigneeClickupUserIds")
            changed = True
        if "tagNames" in upd:
            target["tag_names"] = upd.get("tagNames")
            changed = True
        if "customFields" in upd:
            target["custom_fields"] = _upsert_custom_fields(target.get("custom_fields"), upd.get("customFields"))
            changed = True

        if not changed:
            failures.append({"index": idx, "error": "No valid update fields were provided", "taskId": res.get("taskId")})
            continue

        target["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        # reflect that ClickUp returned some final payload; store minimally
        raw = target.get("raw") if isinstance(target.get("raw"), dict) else {}
        raw["updated_via"] = "update_bulk_tasks"
        target["raw"] = raw

        updated.append(target)
        resolved_any.append(res)

    # If any taskName resolution yielded 0 or >1, per rules operation must be rejected and logged
    name_resolution_errors = [f for f in failures if "taskName resolution" in (f.get("error") or "")]
    if len(name_resolution_errors) > 0:
        op["status"] = "rejected"
        op["error_message"] = "One or more taskName resolutions were ambiguous or missing; bulk update rejected"
        op["failed_count"] = len(failures)
        op["succeeded_count"] = 0
        op["resolved_clickup_ids"] = {"items": resolved_any}
        return _log_and_return(op, _err("CONFLICT", op["error_message"], failures=failures))

    if len(updated) == 0:
        op["status"] = "failed"
        op["error_message"] = "No tasks were updated"
        op["failed_count"] = len(failures)
        op["succeeded_count"] = 0
        op["resolved_clickup_ids"] = {"items": resolved_any}
        return _log_and_return(op, _err("NOT_FOUND", op["error_message"], failures=failures))

    _save("tasks.json", task_rows)

    op["succeeded_count"] = len(updated)
    op["failed_count"] = len(failures)
    op["resolved_clickup_ids"] = {"items": resolved_any}
    op["status"] = ("succeeded" if len(failures) == 0 else "failed")
    if len(failures) > 0:
        op["error_message"] = "One or more task updates failed validation and were not applied"

    resp = {
        "tasks": updated,
        "summary": {
            "requested": len(tasks),
            "updated": len(updated),
            "failed": len(failures),
            "failures": failures,
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }
    return _log_and_return(op, resp)

def delete_bulk_tasks(workspaceId, tasks, options=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []
    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")
    if not isinstance(tasks, list) or len(tasks) < 1:
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array", field="tasks")

    bulk_count = len(tasks)

    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None, succeeded_count=None, failed_count=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "delete_bulk_tasks",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "tasks": tasks, "options": options},
            "resolved_clickup_ids": resolved,
            "bulk_count": bulk_count,
            "succeeded_count": succeeded_count,
            "failed_count": failed_count,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None, succeeded_count=0, failed_count=bulk_count)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None, succeeded_count=0, failed_count=bulk_count)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    tasks_rows = _rows(_load("tasks.json"))
    ents = _rows(_load("hierarchy_entities.json"))

    outcomes = []
    succeeded = 0
    failed = 0

    def _resolve_list_by_name(lname):
        matches = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == lname]
        if len(matches) == 1:
            return matches[0]
        return None

    for idx, spec in enumerate(tasks):
        if not isinstance(spec, dict):
            outcomes.append({"index": idx, "deleted": False, "error": "task spec must be an object"})
            failed += 1
            continue

        tid = spec.get("taskId")
        tname = spec.get("taskName")
        lname = spec.get("listName")
        target = None

        if tid is not None:
            if not isinstance(tid, str) or not tid.strip():
                outcomes.append({"index": idx, "deleted": False, "error": "taskId must be a non-empty string"})
                failed += 1
                continue
            k = tid.strip()
            for tr in tasks_rows:
                if not isinstance(tr, dict):
                    continue
                if tr.get("workspace_id") != ws_id:
                    continue
                if tr.get("id") == k or tr.get("clickup_task_id") == k or (tr.get("custom_id") and tr.get("custom_id") == k):
                    target = tr
                    break
            if target is None:
                outcomes.append({"index": idx, "deleted": False, "error": "Task not found", "taskId": k})
                failed += 1
                continue

        else:
            if not isinstance(tname, str) or not tname.strip():
                outcomes.append({"index": idx, "deleted": False, "error": "taskName is required when taskId is not provided"})
                failed += 1
                continue
            if not isinstance(lname, str) or not lname.strip():
                outcomes.append({"index": idx, "deleted": False, "error": "listName is required when identifying by taskName"})
                failed += 1
                continue
            list_ent = _resolve_list_by_name(lname.strip())
            if list_ent is None:
                outcomes.append({"index": idx, "deleted": False, "error": "List not found or ambiguous for listName", "listName": lname.strip()})
                failed += 1
                continue
            candidates = [tr for tr in tasks_rows if isinstance(tr, dict) and tr.get("workspace_id") == ws_id and tr.get("status") != "deleted" and tr.get("list_entity_id") == list_ent.get("id") and tr.get("name") == tname.strip()]
            if len(candidates) == 0:
                outcomes.append({"index": idx, "deleted": False, "error": "Task not found", "taskName": tname.strip(), "listName": lname.strip()})
                failed += 1
                continue
            if len(candidates) > 1:
                outcomes.append({"index": idx, "deleted": False, "error": "taskName is ambiguous within list", "taskName": tname.strip(), "listName": lname.strip(), "matchCount": len(candidates)})
                failed += 1
                continue
            target = candidates[0]

        # Delete (idempotent)
        if target.get("status") != "deleted":
            now = _now()
            target["status"] = "deleted"
            target["updated_at"] = now
            raw = target.get("raw") if isinstance(target.get("raw"), dict) else {}
            raw["deleted_via"] = "integration_mirror"
            raw["deleted_at"] = now
            target["raw"] = raw

        outcomes.append({"index": idx, "deleted": True, "taskRowId": target.get("id")})
        succeeded += 1

    if succeeded > 0:
        _save("tasks.json", tasks_rows)

    status_val = "succeeded" if failed == 0 else ("failed" if succeeded == 0 else "failed")
    _op_write(status_val, None if failed == 0 else "Some tasks failed to delete", resolved=None, succeeded_count=succeeded, failed_count=failed)

    if succeeded == 0:
        return _err("NOT_FOUND", "No tasks were deleted", outcomes=outcomes)

    return {
        "outcomes": outcomes,
        "counts": {"requested": bulk_count, "succeeded": succeeded, "failed": failed},
        "operation_id": op_id,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_workspace_tasks(workspaceId, tags=None, listIds=None, folderIds=None, spaceIds=None, statuses=None, assignees=None, dueDateFrom=None, dueDateTo=None, startDateFrom=None, startDateTo=None, updatedFrom=None, updatedTo=None, includeDeleted=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    wsp_pat = re.compile(r"^cu_wsp_[0-9A-Z]{3,}$")
    ent_pat = re.compile(r"^cu_ent_[0-9A-Z]{3,}$")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string", field=field)
        try:
            # accept trailing Z
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc), None
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string", field=field)

    def _dt_from_row(val):
        if val is None:
            return None
        if isinstance(val, str):
            try:
                if val.endswith("Z"):
                    return datetime.datetime.fromisoformat(val[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(val)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _cursor_to_offset(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        if not cur.startswith("off:"):
            return None
        try:
            n = int(cur.split(":", 1)[1])
            return n if n >= 0 else None
        except Exception:
            return None

    # ---- load ----
    workspaces = _load("workspaces.json")
    entities = _load("hierarchy_entities.json")
    tasks_rows = _load("tasks.json")
    ops = _load("integration_operations.json")

    # ---- basic validation ----
    if not isinstance(workspaceId, str) or not wsp_pat.match(workspaceId):
        op_id = "cu_op_" + hashlib.sha1((now + "|get_workspace_tasks|bad_workspace").encode("utf-8")).hexdigest()[:12].upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId if isinstance(workspaceId, str) else "unknown",
            "tool_name": "get_workspace_tasks",
            "operation_type": "read",
            "request_params": {"workspaceId": workspaceId, "tags": tags, "listIds": listIds, "folderIds": folderIds, "spaceIds": spaceIds, "statuses": statuses, "assignees": assignees,
                               "dueDateFrom": dueDateFrom, "dueDateTo": dueDateTo, "startDateFrom": startDateFrom, "startDateTo": startDateTo,
                               "updatedFrom": updatedFrom, "updatedTo": updatedTo, "includeDeleted": includeDeleted, "sortBy": sortBy, "sortOrder": sortOrder,
                               "limit": limit, "cursor": cursor},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "rejected",
            "error_message": "workspaceId is invalid",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("VALIDATION_ERROR", "workspaceId is invalid", field="workspaceId")

    workspace = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not workspace:
        op_id = "cu_op_" + hashlib.sha1((now + "|get_workspace_tasks|workspace_not_found").encode("utf-8")).hexdigest()[:12].upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId,
            "tool_name": "get_workspace_tasks",
            "operation_type": "read",
            "request_params": {"workspaceId": workspaceId, "tags": tags, "listIds": listIds, "folderIds": folderIds, "spaceIds": spaceIds, "statuses": statuses, "assignees": assignees,
                               "dueDateFrom": dueDateFrom, "dueDateTo": dueDateTo, "startDateFrom": startDateFrom, "startDateTo": startDateTo,
                               "updatedFrom": updatedFrom, "updatedTo": updatedTo, "includeDeleted": includeDeleted, "sortBy": sortBy, "sortOrder": sortOrder,
                               "limit": limit, "cursor": cursor},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "failed",
            "error_message": "workspace not found",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)

    # read allowed even in read_only; in disabled workspace, reads are allowed by rules (only writes rejected).
    # ---- validate filters & require at least one ----
    def _is_nonempty_array(x):
        return isinstance(x, list) and any((isinstance(i, str) and i != "") or isinstance(i, (int, float, bool, dict)) for i in x)

    has_filter = False
    for v in (tags, listIds, folderIds, spaceIds, statuses, assignees):
        if _is_nonempty_array(v):
            has_filter = True
            break
    for v in (dueDateFrom, dueDateTo, startDateFrom, startDateTo, updatedFrom, updatedTo):
        if v is not None:
            has_filter = True
            break

    if not has_filter:
        op_id = "cu_op_" + hashlib.sha1((now + "|get_workspace_tasks|missing_filters").encode("utf-8")).hexdigest()[:12].upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId,
            "tool_name": "get_workspace_tasks",
            "operation_type": "read",
            "request_params": {"workspaceId": workspaceId, "tags": tags, "listIds": listIds, "folderIds": folderIds, "spaceIds": spaceIds, "statuses": statuses, "assignees": assignees,
                               "dueDateFrom": dueDateFrom, "dueDateTo": dueDateTo, "startDateFrom": startDateFrom, "startDateTo": startDateTo,
                               "updatedFrom": updatedFrom, "updatedTo": updatedTo, "includeDeleted": includeDeleted, "sortBy": sortBy, "sortOrder": sortOrder,
                               "limit": limit, "cursor": cursor},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "rejected",
            "error_message": "At least one filter parameter is required",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("VALIDATION_ERROR", "At least one filter parameter is required")

    # validate ids arrays patterns and existence (existence: entities must belong to workspace & correct type where applicable)
    def _validate_ent_ids(arr, field):
        if arr is None:
            return None
        if not isinstance(arr, list):
            return _err("VALIDATION_ERROR", f"{field} must be an array", field=field)
        for x in arr:
            if not isinstance(x, str) or not ent_pat.match(x):
                return _err("VALIDATION_ERROR", f"{field} contains an invalid id", field=field)
        return None

    for arr, field in ((listIds, "listIds"), (folderIds, "folderIds"), (spaceIds, "spaceIds")):
        e = _validate_ent_ids(arr, field)
        if e:
            return e

    if tags is not None and (not isinstance(tags, list) or any(not isinstance(t, str) for t in tags)):
        return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")
    if statuses is not None and (not isinstance(statuses, list) or any(not isinstance(s, str) for s in statuses)):
        return _err("VALIDATION_ERROR", "statuses must be an array of strings", field="statuses")
    if assignees is not None and (not isinstance(assignees, list) or any(not isinstance(a, str) for a in assignees)):
        return _err("VALIDATION_ERROR", "assignees must be an array of strings", field="assignees")
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        return _err("VALIDATION_ERROR", "includeDeleted must be a boolean", field="includeDeleted")

    if sortBy is not None and sortBy not in ("updated_at", "created_at", "due_date", "start_date", "priority"):
        return _err("VALIDATION_ERROR", "sortBy is invalid", field="sortBy")
    if sortOrder is not None and sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder is invalid", field="sortOrder")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    offset = _cursor_to_offset(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    due_from, e = _parse_dt(dueDateFrom, "dueDateFrom")
    if e: return e
    due_to, e = _parse_dt(dueDateTo, "dueDateTo")
    if e: return e
    start_from, e = _parse_dt(startDateFrom, "startDateFrom")
    if e: return e
    start_to, e = _parse_dt(startDateTo, "startDateTo")
    if e: return e
    upd_from, e = _parse_dt(updatedFrom, "updatedFrom")
    if e: return e
    upd_to, e = _parse_dt(updatedTo, "updatedTo")
    if e: return e

    # ---- integration op log (received->succeeded) ----
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_id = "cu_op_" + hashlib.sha1((started + "|get_workspace_tasks|" + workspaceId).encode("utf-8")).hexdigest()[:12].upper()
    op_row = {
        "id": op_id,
        "workspace_id": workspaceId,
        "tool_name": "get_workspace_tasks",
        "operation_type": "read",
        "request_params": {"workspaceId": workspaceId, "tags": tags, "listIds": listIds, "folderIds": folderIds, "spaceIds": spaceIds, "statuses": statuses, "assignees": assignees,
                           "dueDateFrom": dueDateFrom, "dueDateTo": dueDateTo, "startDateFrom": startDateFrom, "startDateTo": startDateTo,
                           "updatedFrom": updatedFrom, "updatedTo": updatedTo, "includeDeleted": includeDeleted, "sortBy": sortBy, "sortOrder": sortOrder,
                           "limit": limit, "cursor": cursor},
        "resolved_clickup_ids": None,
        "bulk_count": None,
        "succeeded_count": None,
        "failed_count": None,
        "status": "in_progress",
        "error_message": None,
        "started_at": started,
        "finished_at": None,
        "created_at": started,
        "updated_at": started
    }
    ops.append(op_row)
    _save("integration_operations.json", ops)

    # ---- build hierarchy maps for filtering by folders/spaces ----
    ents_by_id = {e.get("id"): e for e in entities if e.get("workspace_id") == workspaceId}
    list_to_folder = {}
    list_to_space = {}

    for e in entities:
        if e.get("workspace_id") != workspaceId:
            continue
        if e.get("entity_type") == "list":
            pid = e.get("parent_entity_id")
            space_id = None
            folder_id = None
            if pid and pid in ents_by_id:
                parent = ents_by_id[pid]
                if parent.get("entity_type") == "folder":
                    folder_id = parent.get("id")
                    # folder's parent should be space
                    spid = parent.get("parent_entity_id")
                    if spid and spid in ents_by_id and ents_by_id[spid].get("entity_type") == "space":
                        space_id = ents_by_id[spid].get("id")
                elif parent.get("entity_type") == "space":
                    space_id = parent.get("id")
            # fall back to space_clickup_id is clickup id not internal id; ignore
            list_to_folder[e.get("id")] = folder_id
            list_to_space[e.get("id")] = space_id

    # validate provided entity ids exist and are correct type
    def _ensure_entities(ids, etype, field):
        if ids is None:
            return None
        for i in ids:
            e = ents_by_id.get(i)
            if not e:
                return _err("NOT_FOUND", f"{field} contains an entity that does not exist", field=field, id=i)
            if e.get("entity_type") != etype:
                return _err("VALIDATION_ERROR", f"{field} must contain {etype} entity ids", field=field, id=i)
            if e.get("status") == "deleted":
                return _err("INVALID_TRANSITION", f"{field} contains a deleted entity", field=field, id=i)
        return None

    e = _ensure_entities(listIds, "list", "listIds")
    if e: return e
    e = _ensure_entities(folderIds, "folder", "folderIds")
    if e: return e
    e = _ensure_entities(spaceIds, "space", "spaceIds")
    if e: return e

    tagset = set([t for t in tags or [] if isinstance(t, str) and t != ""])
    statusset = set([s for s in statuses or [] if isinstance(s, str) and s != ""])
    assigneeset = set([a for a in assignees or [] if isinstance(a, str) and a != ""])

    # ---- filter tasks (workspace-wide only active unless includeDeleted) ----
    want_deleted = bool(includeDeleted) if includeDeleted is not None else False

    filtered = []
    for tr in tasks_rows:
        if tr.get("workspace_id") != workspaceId:
            continue
        st = tr.get("status")
        if st != "active" and not (want_deleted and st == "deleted"):
            continue

        # listIds filter
        if listIds is not None and len(listIds) > 0:
            if tr.get("list_entity_id") not in set(listIds):
                continue

        # folderIds/spaceIds via list parent relationships
        lid = tr.get("list_entity_id")
        if folderIds is not None and len(folderIds) > 0:
            if list_to_folder.get(lid) not in set(folderIds):
                continue
        if spaceIds is not None and len(spaceIds) > 0:
            if list_to_space.get(lid) not in set(spaceIds):
                continue

        # statuses filter
        if statusset:
            if tr.get("status_text") not in statusset:
                continue

        # assignees contains
        if assigneeset:
            a = tr.get("assignee_clickup_user_ids") or []
            if not isinstance(a, list):
                a = []
            if not any(x in assigneeset for x in a if isinstance(x, str)):
                continue

        # tags contains any
        if tagset:
            tn = tr.get("tag_names") or []
            if not isinstance(tn, list):
                tn = []
            if not any(x in tagset for x in tn if isinstance(x, str)):
                continue

        # date ranges
        if due_from or due_to:
            dtd = _dt_from_row(tr.get("due_date"))
            if dtd is None:
                continue
            if due_from and dtd < due_from:
                continue
            if due_to and dtd > due_to:
                continue

        if start_from or start_to:
            dts = _dt_from_row(tr.get("start_date"))
            if dts is None:
                continue
            if start_from and dts < start_from:
                continue
            if start_to and dts > start_to:
                continue

        if upd_from or upd_to:
            dtu = _dt_from_row(tr.get("updated_at"))
            if dtu is None:
                continue
            if upd_from and dtu < upd_from:
                continue
            if upd_to and dtu > upd_to:
                continue

        filtered.append(tr)

    total = len(filtered)

    # ---- sort ----
    sb = sortBy or "updated_at"
    so = sortOrder or "desc"
    reverse = (so == "desc")

    def _sort_key(tr):
        if sb in ("updated_at", "created_at", "due_date", "start_date"):
            dt = _dt_from_row(tr.get(sb))
            # None sorts last in asc, first in desc; emulate by sentinel
            if dt is None:
                return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if reverse else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            return dt
        if sb == "priority":
            p = tr.get("priority")
            if not isinstance(p, int):
                return -10**9 if reverse else 10**9
            return p
        return tr.get("updated_at") or ""

    filtered.sort(key=_sort_key, reverse=reverse)

    # ---- paginate ----
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"off:{next_offset}" if has_more else None

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for o in ops:
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["finished_at"] = finished
            o["updated_at"] = finished
            break
    _save("integration_operations.json", ops)

    return {
        "tasks": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "nextCursor": next_cursor,
        "hasMore": has_more,
        "latency_ms": int((time.time() - t0) * 1000),
        "operation_id": op_id
    }

def get_task_time_entries(workspaceId, taskId=None, taskName=None, listName=None, clickupUserIds=None, billable=None, tags=None, startFrom=None, startTo=None, includeRunning=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    wsp_pat = re.compile(r"^cu_wsp_[0-9A-Z]{3,}$")
    tsk_pat = re.compile(r"^cu_tsk_[0-9A-Z]{3,}$")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string", field=field)
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc), None
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 datetime string", field=field)

    def _dt_from_row(val):
        if val is None:
            return None
        if isinstance(val, str):
            try:
                if val.endswith("Z"):
                    return datetime.datetime.fromisoformat(val[:-1]).replace(tzinfo=datetime.timezone.utc)
                dt = datetime.datetime.fromisoformat(val)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _cursor_to_offset(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        if not cur.startswith("off:"):
            return None
        try:
            n = int(cur.split(":", 1)[1])
            return n if n >= 0 else None
        except Exception:
            return None

    # ---- load ----
    workspaces = _load("workspaces.json")
    entities = _load("hierarchy_entities.json")
    tasks_rows = _load("tasks.json")
    time_rows = _load("time_entries.json")
    ops = _load("integration_operations.json")

    if not isinstance(workspaceId, str) or not wsp_pat.match(workspaceId):
        op_id = "cu_op_" + hashlib.sha1((now + "|get_task_time_entries|bad_workspace").encode("utf-8")).hexdigest()[:12].upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId if isinstance(workspaceId, str) else "unknown",
            "tool_name": "get_task_time_entries",
            "operation_type": "read",
            "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "clickupUserIds": clickupUserIds,
                               "billable": billable, "tags": tags, "startFrom": startFrom, "startTo": startTo, "includeRunning": includeRunning,
                               "limit": limit, "cursor": cursor},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "rejected",
            "error_message": "workspaceId is invalid",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("VALIDATION_ERROR", "workspaceId is invalid", field="workspaceId")

    workspace = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not workspace:
        op_id = "cu_op_" + hashlib.sha1((now + "|get_task_time_entries|workspace_not_found").encode("utf-8")).hexdigest()[:12].upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId,
            "tool_name": "get_task_time_entries",
            "operation_type": "read",
            "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "clickupUserIds": clickupUserIds,
                               "billable": billable, "tags": tags, "startFrom": startFrom, "startTo": startTo, "includeRunning": includeRunning,
                               "limit": limit, "cursor": cursor},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "failed",
            "error_message": "workspace not found",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)

    # ---- validate params ----
    resolved = {}

    if taskId is not None:
        if not isinstance(taskId, str) or not tsk_pat.match(taskId):
            return _err("VALIDATION_ERROR", "taskId is invalid", field="taskId")
    else:
        if taskName is None or not isinstance(taskName, str) or not taskName.strip():
            return _err("VALIDATION_ERROR", "taskId or taskName is required", field="taskName")
        if listName is not None and (not isinstance(listName, str) or not listName.strip()):
            return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided", field="listName")

    if clickupUserIds is not None and (not isinstance(clickupUserIds, list) or any(not isinstance(x, str) for x in clickupUserIds)):
        return _err("VALIDATION_ERROR", "clickupUserIds must be an array of strings", field="clickupUserIds")
    if billable is not None and not isinstance(billable, bool):
        return _err("VALIDATION_ERROR", "billable must be a boolean", field="billable")
    if tags is not None and (not isinstance(tags, list) or any(not isinstance(t, str) for t in tags)):
        return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")
    if includeRunning is not None and not isinstance(includeRunning, bool):
        return _err("VALIDATION_ERROR", "includeRunning must be a boolean", field="includeRunning")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    offset = _cursor_to_offset(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    start_from, e = _parse_dt(startFrom, "startFrom")
    if e: return e
    start_to, e = _parse_dt(startTo, "startTo")
    if e: return e

    # ---- resolve task ----
    task_row = None
    if taskId is not None:
        task_row = next((t for t in tasks_rows if t.get("id") == taskId and t.get("workspace_id") == workspaceId), None)
        if not task_row:
            # log and return not found
            op_id = "cu_op_" + hashlib.sha1((now + "|get_task_time_entries|task_not_found").encode("utf-8")).hexdigest()[:12].upper()
            ops.append({
                "id": op_id,
                "workspace_id": workspaceId,
                "tool_name": "get_task_time_entries",
                "operation_type": "read",
                "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "clickupUserIds": clickupUserIds,
                                   "billable": billable, "tags": tags, "startFrom": startFrom, "startTo": startTo, "includeRunning": includeRunning,
                                   "limit": limit, "cursor": cursor},
                "resolved_clickup_ids": None,
                "bulk_count": None,
                "succeeded_count": None,
                "failed_count": None,
                "status": "failed",
                "error_message": "task not found",
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now
            })
            _save("integration_operations.json", ops)
            return _err("NOT_FOUND", "Task not found", taskId=taskId)
        resolved["taskId"] = task_row.get("id")
        resolved["clickup_task_id"] = task_row.get("clickup_task_id")
    else:
        # resolve by name, optionally scoped by listName (if present); if unscoped and ambiguous -> reject
        candidates = [t for t in tasks_rows if t.get("workspace_id") == workspaceId and t.get("name") == taskName]
        if listName is not None:
            # resolve listName uniquely to active list in workspace; if ambiguous -> reject
            lists = [e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == listName]
            if len(lists) == 0:
                return _err("NOT_FOUND", "listName not found", listName=listName)
            if len(lists) > 1:
                return _err("CONFLICT", "Ambiguous listName; cannot resolve taskName uniquely", listName=listName, matches=len(lists))
            lid = lists[0].get("id")
            candidates = [t for t in candidates if t.get("list_entity_id") == lid]
            resolved["listEntityId"] = lid

        if len(candidates) == 0:
            op_id = "cu_op_" + hashlib.sha1((now + "|get_task_time_entries|taskname_not_found").encode("utf-8")).hexdigest()[:12].upper()
            ops.append({
                "id": op_id,
                "workspace_id": workspaceId,
                "tool_name": "get_task_time_entries",
                "operation_type": "read",
                "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "clickupUserIds": clickupUserIds,
                                   "billable": billable, "tags": tags, "startFrom": startFrom, "startTo": startTo, "includeRunning": includeRunning,
                                   "limit": limit, "cursor": cursor},
                "resolved_clickup_ids": resolved,
                "bulk_count": None,
                "succeeded_count": None,
                "failed_count": None,
                "status": "failed",
                "error_message": "task not found by name",
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now
            })
            _save("integration_operations.json", ops)
            return _err("NOT_FOUND", "Task not found", taskName=taskName, listName=listName)
        if len(candidates) > 1:
            # reject ambiguous
            op_id = "cu_op_" + hashlib.sha1((now + "|get_task_time_entries|taskname_ambiguous").encode("utf-8")).hexdigest()[:12].upper()
            ops.append({
                "id": op_id,
                "workspace_id": workspaceId,
                "tool_name": "get_task_time_entries",
                "operation_type": "read",
                "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "clickupUserIds": clickupUserIds,
                                   "billable": billable, "tags": tags, "startFrom": startFrom, "startTo": startTo, "includeRunning": includeRunning,
                                   "limit": limit, "cursor": cursor},
                "resolved_clickup_ids": resolved,
                "bulk_count": None,
                "succeeded_count": None,
                "failed_count": None,
                "status": "rejected",
                "error_message": "Ambiguous taskName; provide taskId or listName",
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now
            })
            _save("integration_operations.json", ops)
            return _err("CONFLICT", "Ambiguous taskName; provide taskId or listName", taskName=taskName, matches=len(candidates))

        task_row = candidates[0]
        resolved["taskId"] = task_row.get("id")
        resolved["clickup_task_id"] = task_row.get("clickup_task_id")

    # ---- log operation in progress ----
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_id = "cu_op_" + hashlib.sha1((started + "|get_task_time_entries|" + workspaceId + "|" + str(resolved.get("taskId",""))).encode("utf-8")).hexdigest()[:12].upper()
    op_row = {
        "id": op_id,
        "workspace_id": workspaceId,
        "tool_name": "get_task_time_entries",
        "operation_type": "read",
        "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "clickupUserIds": clickupUserIds,
                           "billable": billable, "tags": tags, "startFrom": startFrom, "startTo": startTo, "includeRunning": includeRunning,
                           "limit": limit, "cursor": cursor},
        "resolved_clickup_ids": resolved,
        "bulk_count": None,
        "succeeded_count": None,
        "failed_count": None,
        "status": "in_progress",
        "error_message": None,
        "started_at": started,
        "finished_at": None,
        "created_at": started,
        "updated_at": started
    }
    ops.append(op_row)
    _save("integration_operations.json", ops)

    # ---- filter time entries ----
    want_running = True if includeRunning is None else bool(includeRunning)
    user_set = set([u for u in (clickupUserIds or []) if isinstance(u, str) and u != ""])
    tag_set = set([t for t in (tags or []) if isinstance(t, str) and t != ""])

    rows = []
    for te in time_rows:
        if te.get("workspace_id") != workspaceId:
            continue
        if te.get("status") == "deleted":
            continue
        if te.get("task_id") != task_row.get("id"):
            continue
        if not want_running and te.get("status") == "running":
            continue
        if user_set:
            if te.get("clickup_user_id") not in user_set:
                continue
        if billable is not None:
            if te.get("billable") is None:
                continue
            if bool(te.get("billable")) != bool(billable):
                continue
        if tag_set:
            tn = te.get("tag_names") or []
            if not isinstance(tn, list):
                tn = []
            if not any(x in tag_set for x in tn if isinstance(x, str)):
                continue

        st = _dt_from_row(te.get("start_at"))
        if start_from or start_to:
            if st is None:
                continue
            if start_from and st < start_from:
                continue
            if start_to and st > start_to:
                continue

        rows.append(te)

    # sort by start_at desc (common listing); stable secondary by id
    def _k(te):
        dt = _dt_from_row(te.get("start_at"))
        if dt is None:
            dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, te.get("id") or "")
    rows.sort(key=_k, reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"off:{next_offset}" if has_more else None

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for o in ops:
        if o.get("id") == op_id:
            o["status"] = "succeeded"
            o["finished_at"] = finished
            o["updated_at"] = finished
            break
    _save("integration_operations.json", ops)

    return {
        "task": task_row,
        "time_entries": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "nextCursor": next_cursor,
        "hasMore": has_more,
        "latency_ms": int((time.time() - t0) * 1000),
        "operation_id": op_id
    }

def stop_time_tracking(workspaceId, description=None, tags=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
        return _err("VALIDATION_ERROR", "workspaceId is invalid; expected pattern ^cu_wsp_[0-9A-Z]+$")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string")
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(x, str)) for x in tags):
            return _err("VALIDATION_ERROR", "tags must be an array of strings")

    workspaces = _load("workspaces.json")
    time_entries = _load("time_entries.json")
    ops = _load("integration_operations.json")

    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws:
        op_id = "cu_op_" + uuid.uuid4().hex.upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId,
            "tool_name": "stop_time_tracking",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "description": description, "tags": tags},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "failed",
            "error_message": "Workspace not found",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)

    # Enforce workspace status for write operations
    if ws.get("status") in ("disabled", "read_only"):
        op_id = "cu_op_" + uuid.uuid4().hex.upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId,
            "tool_name": "stop_time_tracking",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "description": description, "tags": tags},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "rejected",
            "error_message": f"Workspace is {ws.get('status')}; write operations are not allowed",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("UNAUTHORIZED", "Workspace does not allow write operations in its current status", status=ws.get("status"))

    running = [te for te in time_entries if te.get("workspace_id") == workspaceId and te.get("status") == "running" and te.get("is_running") is True]
    if len(running) == 0:
        op_id = "cu_op_" + uuid.uuid4().hex.upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId,
            "tool_name": "stop_time_tracking",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "description": description, "tags": tags},
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "failed",
            "error_message": "No running time entry found",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("NOT_FOUND", "No running time entry found")
    if len(running) > 1:
        # Repair to enforce invariant: keep the most recent as running, stop others
        def _parse(dt):
            try:
                if isinstance(dt, str) and dt.endswith("Z"):
                    return datetime.datetime.fromisoformat(dt[:-1])
                if isinstance(dt, str):
                    return datetime.datetime.fromisoformat(dt)
            except Exception:
                return None
            return None
        running_sorted = sorted(running, key=lambda r: (_parse(r.get("start_at")) or datetime.datetime.min), reverse=True)
        keep = running_sorted[0]
        for r in running_sorted[1:]:
            # transition to stopped
            if r.get("status") == "running":
                r["status"] = "stopped"
            r["is_running"] = False
            if r.get("end_at") is None:
                r["end_at"] = now
            # duration if possible
            try:
                st = _parse(r.get("start_at"))
                en = _parse(r.get("end_at"))
                if st and en and en >= st:
                    r["duration_ms"] = int((en - st).total_seconds() * 1000)
                else:
                    r["duration_ms"] = r.get("duration_ms") if isinstance(r.get("duration_ms"), int) else 0
            except Exception:
                r["duration_ms"] = r.get("duration_ms") if isinstance(r.get("duration_ms"), int) else 0
            r["updated_at"] = now
        target = keep
    else:
        target = running[0]

    # Stop target
    if target.get("status") != "running":
        op_id = "cu_op_" + uuid.uuid4().hex.upper()
        ops.append({
            "id": op_id,
            "workspace_id": workspaceId,
            "tool_name": "stop_time_tracking",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "description": description, "tags": tags},
            "resolved_clickup_ids": {"timeEntryId": target.get("id")},
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "failed",
            "error_message": "Invariant violation: selected running entry is not in running status",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)
        return _err("CONFLICT", "Selected time entry is not running", timeEntryId=target.get("id"))

    # Apply optional updates
    if description is not None:
        target["description"] = description
    if tags is not None:
        target["tag_names"] = tags

    target["end_at"] = now
    target["is_running"] = False
    target["status"] = "stopped"

    # Compute duration
    try:
        def _parse(dt):
            if isinstance(dt, str) and dt.endswith("Z"):
                return datetime.datetime.fromisoformat(dt[:-1])
            if isinstance(dt, str):
                return datetime.datetime.fromisoformat(dt)
            return None
        st = _parse(target.get("start_at"))
        en = _parse(target.get("end_at"))
        if st and en and en >= st:
            target["duration_ms"] = int((en - st).total_seconds() * 1000)
        else:
            target["duration_ms"] = 0
    except Exception:
        target["duration_ms"] = 0

    target["updated_at"] = now

    op_id = "cu_op_" + uuid.uuid4().hex.upper()
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ops.append({
        "id": op_id,
        "workspace_id": workspaceId,
        "tool_name": "stop_time_tracking",
        "operation_type": "write",
        "request_params": {"workspaceId": workspaceId, "description": description, "tags": tags},
        "resolved_clickup_ids": {"timeEntryId": target.get("id")},
        "bulk_count": None,
        "succeeded_count": None,
        "failed_count": None,
        "status": "succeeded",
        "error_message": None,
        "started_at": now,
        "finished_at": finished,
        "created_at": now,
        "updated_at": finished
    })

    _save("time_entries.json", time_entries)
    _save("integration_operations.json", ops)

    return {
        "time_entry": target,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "operation_id": op_id
        }
    }

def add_time_entry(workspaceId, startAt, durationMs, taskId=None, taskName=None, listName=None, description=None, billable=None, tags=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    op_id = "cu_op_" + uuid.uuid4().hex[:12].upper()
    def _op_init(ws_id):
        ops = _load("integration_operations.json")
        ops.append({
            "id": op_id,
            "workspace_id": ws_id,
            "tool_name": "add_time_entry",
            "operation_type": "write",
            "request_params": {
                "workspaceId": workspaceId, "startAt": startAt, "durationMs": durationMs,
                "taskId": taskId, "taskName": taskName, "listName": listName,
                "description": description, "billable": billable, "tags": tags
            },
            "resolved_clickup_ids": None,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": "received",
            "error_message": None,
            "started_at": now,
            "finished_at": None,
            "created_at": now,
            "updated_at": now
        })
        _save("integration_operations.json", ops)

    def _op_finish(status1, error_message=None, resolved=None):
        ops = _load("integration_operations.json")
        fin = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for r in reversed(ops):
            if r.get("id") == op_id:
                allowed = {
                    "received": {"in_progress", "rejected"},
                    "in_progress": {"succeeded", "failed"},
                    "succeeded": set(),
                    "failed": set(),
                    "rejected": set(),
                }
                cur = r.get("status")
                if cur in allowed and status1 in allowed[cur]:
                    r["status"] = status1
                else:
                    r["status"] = "failed"
                    error_message = error_message or "Illegal operation status transition"
                r["error_message"] = error_message
                r["resolved_clickup_ids"] = resolved
                r["finished_at"] = fin
                r["updated_at"] = fin
                break
        _save("integration_operations.json", ops)

    def _resolve_workspace(wid):
        ws = _load("workspaces.json")
        if isinstance(wid, str):
            for w in ws:
                if w.get("id") == wid or w.get("clickup_team_id") == wid:
                    return w
        return None

    def _parse_iso(dt_str, field):
        if not isinstance(dt_str, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string", field=field)
        try:
            if dt_str.endswith("Z"):
                dt = datetime.datetime.fromisoformat(dt_str[:-1]).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(dt_str)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None, microsecond=0)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string", field=field)

    def _resolve_list_by_name(workspace_row, list_name):
        ents = _load("hierarchy_entities.json")
        wsid = workspace_row.get("id")
        candidates = [e for e in ents if e.get("workspace_id") == wsid and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == list_name]
        if len(candidates) == 0:
            return None, _err("NOT_FOUND", "List not found", field="listName")
        if len(candidates) > 1:
            return None, _err("CONFLICT", "listName is ambiguous; provide taskId instead", field="listName", matches=[c.get("clickup_id") for c in candidates])
        return candidates[0], None

    def _resolve_task(workspace_row):
        ts = _load("tasks.json")
        wsid = workspace_row.get("id")
        if taskId is not None:
            if not isinstance(taskId, str) or not taskId:
                return None, _err("VALIDATION_ERROR", "taskId must be a string", field="taskId"), None
            for t in ts:
                if t.get("workspace_id") == wsid and t.get("status") == "active" and t.get("id") == taskId:
                    return t, None, {"taskId": t.get("id"), "clickupTaskId": t.get("clickup_task_id")}
            return None, _err("NOT_FOUND", "Task not found", field="taskId"), None

        if taskName is None:
            return None, None, None  # task is optional for time entries
        if not isinstance(taskName, str) or not taskName.strip():
            return None, _err("VALIDATION_ERROR", "taskName must be a non-empty string", field="taskName"), None

        list_ent = None
        resolved = {"taskName": taskName}
        if listName is not None:
            if not isinstance(listName, str) or not listName.strip():
                return None, _err("VALIDATION_ERROR", "listName must be a non-empty string", field="listName"), None
            list_ent, le = _resolve_list_by_name(workspace_row, listName)
            if le:
                return None, le, None
            resolved.update({"listName": listName, "listEntityId": list_ent.get("id")})

        candidates = []
        for t in ts:
            if t.get("workspace_id") != wsid or t.get("status") != "active":
                continue
            if t.get("name") != taskName:
                continue
            if list_ent is not None and t.get("list_entity_id") != list_ent.get("id"):
                continue
            candidates.append(t)

        if len(candidates) == 0:
            return None, _err("NOT_FOUND", "Task not found", field="taskName"), resolved
        if len(candidates) > 1:
            return None, _err("CONFLICT", "taskName is ambiguous; provide taskId or listName", field="taskName", matches=[c.get("id") for c in candidates]), resolved

        t = candidates[0]
        resolved.update({"taskId": t.get("id"), "clickupTaskId": t.get("clickup_task_id")})
        return t, None, resolved

    _op_init(workspaceId if isinstance(workspaceId, str) else "unknown")

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        _op_finish("rejected", "workspaceId must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspaceId must be a non-empty string", field="workspaceId")
    if not isinstance(durationMs, int) or durationMs < 1:
        _op_finish("rejected", "durationMs must be an integer >= 1")
        return _err("VALIDATION_ERROR", "durationMs must be an integer >= 1", field="durationMs")
    if description is not None and not isinstance(description, str):
        _op_finish("rejected", "description must be a string")
        return _err("VALIDATION_ERROR", "description must be a string", field="description")
    if billable is not None and not isinstance(billable, bool):
        _op_finish("rejected", "billable must be a boolean")
        return _err("VALIDATION_ERROR", "billable must be a boolean", field="billable")
    if tags is not None and (not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags)):
        _op_finish("rejected", "tags must be an array of strings")
        return _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")

    workspace = _resolve_workspace(workspaceId)
    if not workspace:
        _op_finish("rejected", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")
    if workspace.get("status") in ("disabled", "read_only"):
        _op_finish("rejected", f"Workspace is {workspace.get('status')}; write operations are not allowed")
        return _err("UNAUTHORIZED", f"Workspace is {workspace.get('status')}; write operations are not allowed")

    start_dt, derr = _parse_iso(startAt, "startAt")
    if derr:
        _op_finish("rejected", derr["error"]["message"])
        return derr

    _op_finish("in_progress")

    task_row, terr, resolved = _resolve_task(workspace)
    if terr:
        _op_finish("rejected", terr["error"]["message"], resolved=resolved)
        return terr

    end_dt = start_dt + datetime.timedelta(milliseconds=durationMs)
    start_iso = start_dt.replace(microsecond=0).isoformat() + "Z"
    end_iso = end_dt.replace(microsecond=0).isoformat() + "Z"

    time_rows = _load("time_entries.json")
    existing_clickup = {r.get("clickup_time_entry_id") for r in time_rows if isinstance(r, dict) and r.get("clickup_time_entry_id")}
    new_clickup_id = "te_" + uuid.uuid4().hex[:16]
    while new_clickup_id in existing_clickup:
        new_clickup_id = "te_" + uuid.uuid4().hex[:16]

    new_id = "cu_time_" + uuid.uuid4().hex[:22].upper()
    new_row = {
        "id": new_id,
        "workspace_id": workspace.get("id"),
        "task_id": (task_row.get("id") if task_row else None),
        "clickup_time_entry_id": new_clickup_id,
        "clickup_user_id": None,
        "description": description,
        "billable": billable,
        "tag_names": tags if tags is not None else None,
        "start_at": start_iso,
        "end_at": end_iso,
        "duration_ms": durationMs,
        "is_running": False,
        "source": "manual",
        "status": "stopped",
        "raw": {"created_via": "integration_mirror"},
        "created_at": now,
        "updated_at": now,
    }

    time_rows.append(new_row)
    _save("time_entries.json", time_rows)

    _op_finish("succeeded", resolved={**(resolved or {}), "timeEntryId": new_id, "clickupTimeEntryId": new_clickup_id})
    return {"time_entry": new_row}

def create_list(workspaceId, spaceId=None, spaceName=None, name=None, content=None, dueDate=None, priority=None, assigneeClickupUserId=None, status=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []
    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()
    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 string", field=field)
        v = s.strip()
        try:
            datetime.datetime.fromisoformat(v[:-1] if v.endswith("Z") else v)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be ISO 8601 date-time", field=field)
        return v, None

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")
    if not isinstance(name, str) or not name.strip():
        nm_err = _err("VALIDATION_ERROR", "name is required", field="name")
    else:
        nm_err = None

    due_v, due_e = _parse_dt(dueDate, "dueDate")
    if due_e:
        dt_err = due_e
    else:
        dt_err = None

    if priority is not None and not isinstance(priority, int):
        pr_err = _err("VALIDATION_ERROR", "priority must be an integer", field="priority")
    else:
        pr_err = None

    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "create_list",
            "operation_type": "write",
            "request_params": {
                "workspaceId": workspaceId,
                "spaceId": spaceId,
                "spaceName": spaceName,
                "name": name,
                "content": content,
                "dueDate": dueDate,
                "priority": priority,
                "assigneeClickupUserId": assigneeClickupUserId,
                "status": status,
            },
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    if nm_err or dt_err or pr_err:
        first = nm_err or dt_err or pr_err
        _op_write("rejected", first["error"]["message"], resolved=None)
        return first

    if (spaceId is None or (isinstance(spaceId, str) and not spaceId.strip())) and (spaceName is None or (isinstance(spaceName, str) and not spaceName.strip())):
        _op_write("rejected", "Either spaceId or spaceName is required", resolved=None)
        return _err("VALIDATION_ERROR", "Either spaceId or spaceName is required", field="spaceId")

    ents = _rows(_load("hierarchy_entities.json"))
    resolved = {}
    space_ent = None

    if spaceId is not None and isinstance(spaceId, str) and spaceId.strip():
        sid = spaceId.strip()
        for e in ents:
            if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and (e.get("id") == sid or e.get("clickup_id") == sid):
                space_ent = e
                break
        resolved["spaceId"] = sid

    if space_ent is None:
        sname = spaceName.strip() if isinstance(spaceName, str) else ""
        matches = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and e.get("name") == sname]
        if len(matches) == 0:
            _op_write("failed", "Space not found", resolved={"spaceName": sname})
            return _err("NOT_FOUND", "Space not found", field="spaceName")
        if len(matches) > 1:
            _op_write("rejected", "spaceName is ambiguous; provide spaceId", resolved={"spaceName": sname, "matchCount": len(matches)})
            return _err("CONFLICT", "spaceName is ambiguous; provide spaceId", field="spaceName", matchCount=len(matches))
        space_ent = matches[0]
        resolved["spaceName"] = sname

    # Create list entity
    now = _now()
    new_ent = {
        "id": _gen_id("cu_ent_"),
        "workspace_id": ws_id,
        "entity_type": "list",
        "clickup_id": _gen_id("90"),
        "parent_entity_id": space_ent.get("id"),
        "space_clickup_id": space_ent.get("clickup_id"),
        "name": name.strip(),
        "content": content if isinstance(content, str) else (content if content is None else str(content)),
        "archived": False,
        "override_statuses": None,
        "status": "active",
        "raw": {"created_via": "integration_mirror", "dueDate": due_v, "priority": priority, "assigneeClickupUserId": assigneeClickupUserId, "statusText": status},
        "created_at": now,
        "updated_at": now,
    }
    ents.append(new_ent)
    _save("hierarchy_entities.json", ents)

    _op_write("succeeded", None, resolved={**resolved, "spaceEntityId": space_ent.get("id"), "listEntityId": new_ent.get("id")})
    return {"list": new_ent, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

