            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    if nm_err:
        _op_write("rejected", nm_err["error"]["message"], resolved=None)
        return nm_err

    # Must provide folderId or folderName; if folderName used, must include spaceId/spaceName to disambiguate (business rule)
    if (folderId is None or (isinstance(folderId, str) and not folderId.strip())) and (folderName is None or (isinstance(folderName, str) and not folderName.strip())):
        _op_write("rejected", "Either folderId or folderName is required", resolved=None)
        return _err("VALIDATION_ERROR", "Either folderId or folderName is required", field="folderId")

    ents = _rows(_load("hierarchy_entities.json"))
    resolved = {}
    folder_ent = None

    if folderId is not None and isinstance(folderId, str) and folderId.strip():
        fid = folderId.strip()
        for e in ents:
            if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "folder" and e.get("status") == "active" and (e.get("id") == fid or e.get("clickup_id") == fid):
                folder_ent = e
                break
        resolved["folderId"] = fid

    if folder_ent is None:
        if not isinstance(folderName, str) or not folderName.strip():
            _op_write("rejected", "folderName is required when folderId is not provided", resolved=None)
            return _err("VALIDATION_ERROR", "folderName is required when folderId is not provided", field="folderName")
        # folderName without space scope must be rejected
        if (spaceId is None or (isinstance(spaceId, str) and not spaceId.strip())) and (spaceName is None or (isinstance(spaceName, str) and not spaceName.strip())):
            _op_write("rejected", "spaceId or spaceName is required to resolve folderName", resolved={"folderName": folderName.strip()})
            return _err("VALIDATION_ERROR", "spaceId or spaceName is required to resolve folderName", field="spaceId")

        # resolve space to scope folderName
        space_ent = None
        if spaceId is not None and isinstance(spaceId, str) and spaceId.strip():
            sid = spaceId.strip()
            for e in ents:
                if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and (e.get("id") == sid or e.get("clickup_id") == sid):
                    space_ent = e
                    break
            resolved["spaceId"] = sid
        if space_ent is None:
            sname = spaceName.strip() if isinstance(spaceName, str) else ""
            sm = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and e.get("name") == sname]
            if len(sm) == 0:
                _op_write("failed", "Space not found", resolved={"spaceName": sname, "folderName": folderName.strip()})
                return _err("NOT_FOUND", "Space not found", field="spaceName")
            if len(sm) > 1:
                _op_write("rejected", "spaceName is ambiguous; provide spaceId", resolved={"spaceName": sname, "matchCount": len(sm)})
                return _err("CONFLICT", "spaceName is ambiguous; provide spaceId", field="spaceName", matchCount=len(sm))
            space_ent = sm[0]
            resolved["spaceName"] = sname

        fname = folderName.strip()
        fm = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "folder" and e.get("status") == "active" and e.get("name") == fname and e.get("parent_entity_id") == space_ent.get("id")]
        if len(fm) == 0:
            _op_write("failed", "Folder not found", resolved={**resolved, "folderName": fname})
            return _err("NOT_FOUND", "Folder not found", field="folderName")
        if len(fm) > 1:
            _op_write("rejected", "folderName is ambiguous within space; provide folderId", resolved={**resolved, "folderName": fname, "matchCount": len(fm)})
            return _err("CONFLICT", "folderName is ambiguous within space; provide folderId", field="folderName", matchCount=len(fm))
        folder_ent = fm[0]
        resolved["folderName"] = fname

    # Create list entity under folder
    now = _now()
    # Need space_clickup_id from folder
    new_ent = {
        "id": _gen_id("cu_ent_"),
        "workspace_id": ws_id,
        "entity_type": "list",
        "clickup_id": _gen_id("90"),
        "parent_entity_id": folder_ent.get("id"),
        "space_clickup_id": folder_ent.get("space_clickup_id"),
        "name": name.strip(),
        "content": content if isinstance(content, str) else (content if content is None else str(content)),
        "archived": False,
        "override_statuses": None,
        "status": "active",
        "raw": {"created_via": "integration_mirror", "statusText": status},
        "created_at": now,
        "updated_at": now,
    }
    ents.append(new_ent)
    _save("hierarchy_entities.json", ents)

    _op_write("succeeded", None, resolved={**resolved, "folderEntityId": folder_ent.get("id"), "listEntityId": new_ent.get("id")})
    return {"list": new_ent, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def get_list(workspaceId, listId=None, listName=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _op_log(workspace_id, status, operation_type, request_params, error_message=None, resolved_clickup_ids=None):
        ops = _load("integration_operations.json")
        rid = "op_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + os.urandom(3).hex()
        now = _iso_now()
        op = {
            "id": rid,
            "workspace_id": workspace_id,
            "tool_name": "get_list",
            "operation_type": operation_type,
            "request_params": request_params,
            "resolved_clickup_ids": resolved_clickup_ids,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status,
            "error_message": error_message,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("integration_operations.json", ops)
        return op

    req_params = {"workspaceId": workspaceId, "listId": listId, "listName": listName}

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
        _op_log(workspaceId if isinstance(workspaceId, str) else "cu_wsp_INVALID", "rejected", "read", req_params, error_message="Invalid workspaceId.")
        return _err("VALIDATION_ERROR", "Invalid workspaceId.", field="workspaceId")

    if listId is None and (listName is None or (isinstance(listName, str) and not listName.strip())):
        _op_log(workspaceId, "rejected", "read", req_params, error_message="Either listId or listName is required.")
        return _err("VALIDATION_ERROR", "Either listId or listName is required.", field="listId")

    if listId is not None and (not isinstance(listId, str) or not re.match(r"^cu_ent_[0-9A-Z]+$", listId)):
        _op_log(workspaceId, "rejected", "read", req_params, error_message="Invalid listId.")
        return _err("VALIDATION_ERROR", "Invalid listId.", field="listId")

    if listName is not None and not isinstance(listName, str):
        _op_log(workspaceId, "rejected", "read", req_params, error_message="listName must be a string.")
        return _err("VALIDATION_ERROR", "listName must be a string.", field="listName")

    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not wsp:
        _op_log(workspaceId, "failed", "read", req_params, error_message="Workspace not found.")
        return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

    entities = _load("hierarchy_entities.json")

    resolved = {}
    ent = None
    if listId:
        ent = next((e for e in entities if e.get("id") == listId and e.get("workspace_id") == workspaceId and e.get("entity_type") == "list"), None)
        if not ent:
            _op_log(workspaceId, "failed", "read", req_params, error_message="List not found.", resolved_clickup_ids={"listId": listId})
            return _err("NOT_FOUND", "List not found.", listId=listId)
        resolved["listEntityId"] = ent.get("id")
        resolved["listClickupId"] = ent.get("clickup_id")
    else:
        # Business rule about ambiguity when listName matches multiple lists: get_list tool has no scoping params,
        # so reject on multiple matches.
        cands = [e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == listName]
        if len(cands) == 0:
            _op_log(workspaceId, "failed", "read", req_params, error_message="List name could not be resolved.", resolved_clickup_ids={"listName": listName})
            return _err("NOT_FOUND", "List name could not be resolved.", listName=listName)
        if len(cands) > 1:
            _op_log(workspaceId, "rejected", "read", req_params, error_message="Ambiguous listName; provide listId.", resolved_clickup_ids={"listName": listName})
            return _err("CONFLICT", "Ambiguous listName; multiple lists match.", listName=listName, matches=[c.get("id") for c in cands])
        ent = cands[0]
        resolved["listEntityId"] = ent.get("id")
        resolved["listClickupId"] = ent.get("clickup_id")

    # Build hierarchy context
    parent = next((e for e in entities if e.get("id") == ent.get("parent_entity_id") and e.get("workspace_id") == workspaceId), None)
    space = None
    folder = None
    if parent:
        if parent.get("entity_type") == "space":
            space = parent
        elif parent.get("entity_type") == "folder":
            folder = parent
            space = next((e for e in entities if e.get("id") == folder.get("parent_entity_id") and e.get("workspace_id") == workspaceId and e.get("entity_type") == "space"), None)

    resp = {
        "workspace_id": workspaceId,
        "list": ent,
        "context": {
            "space": space,
            "folder": folder,
        },
        "resolved": resolved,
        "latency_ms": int((time.time() - t0) * 1000),
    }

    _op_log(workspaceId, "succeeded", "read", req_params, resolved_clickup_ids=resolved)
    return resp

def update_list(workspaceId, listId=None, listName=None, name=None, content=None, status=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(op_row):
        ops = _load("integration_operations.json")
        ops.append(op_row)
        _save("integration_operations.json", ops)

    def _new_op_id():
        return "op_" + uuid.uuid4().hex

    def _transition_ok(from_s, to_s, transitions):
        return to_s in transitions.get(from_s, [])

    def _resolve_workspace(wid):
        if not isinstance(wid, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", wid):
            return None
        workspaces = _load("workspaces.json")
        for w in workspaces:
            if w.get("id") == wid:
                return w
        return None

    def _resolve_list_entity(workspace_id, clickup_list_id=None, list_name=None):
        entities = _load("hierarchy_entities.json")
        candidates = []
        if clickup_list_id is not None:
            for e in entities:
                if e.get("workspace_id") == workspace_id and e.get("entity_type") == "list" and e.get("clickup_id") == clickup_list_id:
                    return e, {"listId": clickup_list_id}
            return None, None
        # by name
        for e in entities:
            if e.get("workspace_id") == workspace_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == list_name:
                candidates.append(e)
        if len(candidates) == 1:
            return candidates[0], {"listName": list_name, "listId": candidates[0].get("clickup_id")}
        if len(candidates) == 0:
            return None, None
        # ambiguous: tool has no scoping params; must reject
        return "AMBIGUOUS", {"listName": list_name, "matches": [c.get("clickup_id") for c in candidates]}
    try:
        # Validate inputs
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId if isinstance(workspaceId, str) else "unknown",
                "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "workspaceId must match ^cu_wsp_[0-9A-Z]+$",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "Invalid workspaceId format.")
        if listId is None and listName is None:
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "Either listId or listName must be provided.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "Either listId or listName must be provided.")
        if name is None and content is None and status is None:
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "At least one updatable field (name, content, status) must be provided.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "At least one updatable field (name, content, status) must be provided.")
        if name is not None and (not isinstance(name, str) or name.strip() == ""):
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "name must be a non-empty string when provided.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
        if content is not None and not isinstance(content, str):
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "content must be a string when provided.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "content must be a string when provided.")
        if status is not None and status not in ("active", "archived", "deleted"):
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "status must be one of active|archived|deleted.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "status must be one of active|archived|deleted.")

        ws = _resolve_workspace(workspaceId)
        if not ws:
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "failed", "error_message": "Workspace not found.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

        # Workspace write policy
        if ws.get("status") in ("disabled", "read_only"):
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
                "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": f"Workspace status '{ws.get('status')}' does not allow write operations.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("UNAUTHORIZED", "Workspace does not allow write operations.", workspace_status=ws.get("status"))

        op_id = _new_op_id()
        op = {
            "id": op_id, "workspace_id": workspaceId, "tool_name": "update_list", "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
            "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
            "status": "in_progress", "error_message": None,
            "started_at": now, "finished_at": None, "created_at": now, "updated_at": now
        }

        resolved, resolved_map = _resolve_list_entity(workspaceId, clickup_list_id=listId, list_name=listName)
        if resolved == "AMBIGUOUS":
            op["status"] = "rejected"
            op["error_message"] = "Ambiguous listName; provide listId (or additional scoping in a different tool)."
            op["resolved_clickup_ids"] = resolved_map
            op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op["updated_at"] = op["finished_at"]
            _log(op)
            return _err("CONFLICT", "Ambiguous listName; provide listId.", **(resolved_map or {}))
        if not resolved:
            op["status"] = "failed"
            op["error_message"] = "List not found."
            op["resolved_clickup_ids"] = resolved_map
            op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op["updated_at"] = op["finished_at"]
            _log(op)
            return _err("NOT_FOUND", "List not found.", listId=listId, listName=listName)

        entities = _load("hierarchy_entities.json")
        idx = None
        for i, e in enumerate(entities):
            if e.get("id") == resolved.get("id"):
                idx = i
                break
        if idx is None:
            op["status"] = "failed"
            op["error_message"] = "List not found in cache."
            op["resolved_clickup_ids"] = resolved_map
            op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op["updated_at"] = op["finished_at"]
            _log(op)
            return _err("NOT_FOUND", "List not found.", listId=listId, listName=listName)

        # Apply updates
        updated = dict(entities[idx])
        if name is not None:
            updated["name"] = name
        if content is not None:
            updated["content"] = content
        if status is not None:
            from_s = updated.get("status")
            transitions = {"active": ["archived", "deleted"], "archived": ["active", "deleted"], "deleted": []}
            if from_s is None:
                return _err("VALIDATION_ERROR", "List row missing status in datastore.")
            if status != from_s:
                if not _transition_ok(from_s, status, transitions):
                    op["status"] = "failed"
                    op["error_message"] = f"Invalid status transition {from_s} -> {status}"
                    op["resolved_clickup_ids"] = resolved_map
                    op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    op["updated_at"] = op["finished_at"]
                    _log(op)
                    return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=from_s, to_status=status)
                updated["status"] = status
                if status in ("archived", "deleted"):
                    updated["archived"] = True
                elif status == "active":
                    updated["archived"] = False

        updated["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        entities[idx] = updated
        _save("hierarchy_entities.json", entities)

        # Update workspace snapshot if present
        workspaces = _load("workspaces.json")
        widx = None
        for i, w in enumerate(workspaces):
            if w.get("id") == workspaceId:
                widx = i
                break
        if widx is not None and isinstance(workspaces[widx].get("hierarchy_snapshot"), dict):
            snap = dict(workspaces[widx]["hierarchy_snapshot"])
            # Best-effort: update list inside snapshot if structure resembles ClickUp: spaces->folders/lists
            # If structure is unknown, we just bump timestamps.
            def _walk_update(obj):
                if isinstance(obj, dict):
                    if obj.get("id") == updated.get("clickup_id") and obj.get("name") is not None:
                        obj["name"] = updated.get("name", obj.get("name"))
                        obj["content"] = updated.get("content", obj.get("content"))
                        obj["archived"] = updated.get("archived", obj.get("archived"))
                    for k, v in obj.items():
                        _walk_update(v)
                elif isinstance(obj, list):
                    for it in obj:
                        _walk_update(it)
            _walk_update(snap)
            workspaces[widx]["hierarchy_snapshot"] = snap
            workspaces[widx]["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            _save("workspaces.json", workspaces)

        op["status"] = "succeeded"
        op["resolved_clickup_ids"] = resolved_map
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _log(op)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "list": updated,
            "workspace_id": workspaceId,
            "latency_ms": latency_ms
        }
    except Exception as e:
        op = {
            "id": _new_op_id(),
            "workspace_id": workspaceId if isinstance(workspaceId, str) else "unknown",
            "tool_name": "update_list",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName, "name": name, "content": content, "status": status},
            "resolved_clickup_ids": None,
            "bulk_count": None, "succeeded_count": None, "failed_count": None,
            "status": "failed",
            "error_message": f"Internal error: {type(e).__name__}",
            "started_at": now, "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "created_at": now, "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        }
        _log(op)
        return _err("CONFLICT", "Internal error.", detail=f"{type(e).__name__}: {e}")

def delete_list(workspaceId, listId=None, listName=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []
    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")

    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "delete_list",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "listId": listId, "listName": listName},
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    if (listId is None or (isinstance(listId, str) and not listId.strip())) and (listName is None or (isinstance(listName, str) and not listName.strip())):
        _op_write("rejected", "Either listId or listName is required", resolved=None)
        return _err("VALIDATION_ERROR", "Either listId or listName is required", field="listId")

    ents = _rows(_load("hierarchy_entities.json"))
    target = None
    resolved = {}

    if listId is not None and isinstance(listId, str) and listId.strip():
        lid = listId.strip()
        for e in ents:
            if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and (e.get("id") == lid or e.get("clickup_id") == lid):
                target = e
                break
        resolved["listId"] = lid

    if target is None:
        lname = listName.strip() if isinstance(listName, str) else ""
        matches = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == lname]
        if len(matches) == 0:
            _op_write("failed", "List not found", resolved={"listName": lname})
            return _err("NOT_FOUND", "List not found", field="listName")
        if len(matches) > 1:
            _op_write("rejected", "listName is ambiguous; provide listId", resolved={"listName": lname, "matchCount": len(matches)})
            return _err("CONFLICT", "listName is ambiguous; provide listId", field="listName", matchCount=len(matches))
        target = matches[0]
        resolved["listName"] = lname

    if target.get("status") == "deleted":
        _op_write("succeeded", None, resolved={**resolved, "listEntityId": target.get("id")})
        return {"deleted": True, "list": target, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

    # Transition list to deleted; also permanently delete tasks within list
    now = _now()
    target["status"] = "deleted"
    target["archived"] = True
    target["updated_at"] = now
    raw = target.get("raw") if isinstance(target.get("raw"), dict) else {}
    raw["deleted_via"] = "integration_mirror"
    raw["deleted_at"] = now
    target["raw"] = raw

    tasks_rows = _rows(_load("tasks.json"))
    for tr in tasks_rows:
        if isinstance(tr, dict) and tr.get("workspace_id") == ws_id and tr.get("list_entity_id") == target.get("id") and tr.get("status") != "deleted":
            tr["status"] = "deleted"
            tr["updated_at"] = now
            tr_raw = tr.get("raw") if isinstance(tr.get("raw"), dict) else {}
            tr_raw["deleted_via"] = "integration_mirror:list_deleted"
            tr_raw["deleted_at"] = now
            tr["raw"] = tr_raw

    _save("hierarchy_entities.json", ents)
    _save("tasks.json", tasks_rows)

    _op_write("succeeded", None, resolved={**resolved, "listEntityId": target.get("id")})
    return {"deleted": True, "list": target, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def create_folder(workspaceId, name, spaceId=None, spaceName=None, override_statuses=None, **_extra):
