    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")
    if not isinstance(name, str) or not name.strip():
        nm_err = _err("VALIDATION_ERROR", "name is required", field="name")
    else:
