            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    if nm_err or ov_err:
        first = nm_err or ov_err
        _op_write("rejected", first["error"]["message"], resolved=None)
        return first

    if (spaceId is None or (isinstance(spaceId, str) and not spaceId.strip())) and (spaceName is None or (isinstance(spaceName, str) and not spaceName.strip())):
        _op_write("rejected", "Either spaceId or spaceName is required", resolved=None)
        return _err("VALIDATION_ERROR", "Either spaceId or spaceName is required", field="spaceId")

    ents = _rows(_load("hierarchy_entities.json"))
    resolved = {}
    space_ent = None

    if spaceId is not None and isinstance(spaceId, str) and spaceId.strip():
        sid = spaceId.strip()
        for e in ents:
            if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and (e.get("id") == sid or e.get("clickup_id") == sid):
                space_ent = e
                break
        resolved["spaceId"] = sid

    if space_ent is None:
        sname = spaceName.strip() if isinstance(spaceName, str) else ""
        matches = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and e.get("name") == sname]
        if len(matches) == 0:
            _op_write("failed", "Space not found", resolved={"spaceName": sname})
            return _err("NOT_FOUND", "Space not found", field="spaceName")
        if len(matches) > 1:
            _op_write("rejected", "spaceName is ambiguous; provide spaceId", resolved={"spaceName": sname, "matchCount": len(matches)})
            return _err("CONFLICT", "spaceName is ambiguous; provide spaceId", field="spaceName", matchCount=len(matches))
        space_ent = matches[0]
        resolved["spaceName"] = sname

    now = _now()
    new_ent = {
        "id": _gen_id("cu_ent_"),
        "workspace_id": ws_id,
        "entity_type": "folder",
        "clickup_id": _gen_id("90"),
        "parent_entity_id": space_ent.get("id"),
        "space_clickup_id": space_ent.get("clickup_id"),
        "name": name.strip(),
        "content": None,
        "archived": False,
        "override_statuses": override_statuses if override_statuses is not None else None,
        "status": "active",
        "raw": {"created_via": "integration_mirror"},
        "created_at": now,
        "updated_at": now,
    }
    ents.append(new_ent)
    _save("hierarchy_entities.json", ents)

    _op_write("succeeded", None, resolved={**resolved, "spaceEntityId": space_ent.get("id"), "folderEntityId": new_ent.get("id")})
    return {"folder": new_ent, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def get_folder(workspaceId, folderId=None, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(op_row):
        ops = _load("integration_operations.json")
        ops.append(op_row)
        _save("integration_operations.json", ops)

    def _new_op_id():
        return "op_" + uuid.uuid4().hex

    def _resolve_workspace(wid):
        if not isinstance(wid, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", wid):
            return None
        for w in _load("workspaces.json"):
            if w.get("id") == wid:
                return w
        return None

    def _resolve_space_by_id_or_name(workspace_id, clickup_space_id=None, space_name=None):
        entities = _load("hierarchy_entities.json")
        if clickup_space_id is not None:
            for e in entities:
                if e.get("workspace_id") == workspace_id and e.get("entity_type") == "space" and e.get("clickup_id") == clickup_space_id and e.get("status") != "deleted":
                    return e, {"spaceId": clickup_space_id}
            return None, None
        candidates = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("entity_type") == "space" and e.get("status") != "deleted" and e.get("name") == space_name]
        if len(candidates) == 1:
            return candidates[0], {"spaceName": space_name, "spaceId": candidates[0].get("clickup_id")}
        if len(candidates) == 0:
            return None, None
        return "AMBIGUOUS", {"spaceName": space_name, "matches": [c.get("clickup_id") for c in candidates]}

    def _resolve_folder(workspace_id, clickup_folder_id=None, folder_name=None, scoped_space_clickup_id=None):
        entities = _load("hierarchy_entities.json")
        if clickup_folder_id is not None:
            for e in entities:
                if e.get("workspace_id") == workspace_id and e.get("entity_type") == "folder" and e.get("clickup_id") == clickup_folder_id and e.get("status") != "deleted":
                    return e, {"folderId": clickup_folder_id}
            return None, None
        # by name within space scope
        candidates = [e for e in entities if e.get("workspace_id") == workspace_id and e.get("entity_type") == "folder" and e.get("status") == "active" and e.get("name") == folder_name and e.get("space_clickup_id") == scoped_space_clickup_id]
        if len(candidates) == 1:
            return candidates[0], {"folderName": folder_name, "folderId": candidates[0].get("clickup_id"), "spaceId": scoped_space_clickup_id}
        if len(candidates) == 0:
            return None, None
        return "AMBIGUOUS", {"folderName": folder_name, "spaceId": scoped_space_clickup_id, "matches": [c.get("clickup_id") for c in candidates]}

    try:
        # Validate
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]+$", workspaceId):
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId if isinstance(workspaceId, str) else "unknown",
                "tool_name": "get_folder", "operation_type": "read",
                "request_params": {"workspaceId": workspaceId, "folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "workspaceId must match ^cu_wsp_[0-9A-Z]+$",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "Invalid workspaceId format.")
        if folderId is None and folderName is None:
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "get_folder", "operation_type": "read",
                "request_params": {"workspaceId": workspaceId, "folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "Either folderId or folderName must be provided.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "Either folderId or folderName must be provided.")
        if folderName is not None and folderId is None and spaceId is None and spaceName is None:
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "get_folder", "operation_type": "read",
                "request_params": {"workspaceId": workspaceId, "folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "rejected", "error_message": "folderName requires spaceId or spaceName to disambiguate.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("VALIDATION_ERROR", "folderName requires spaceId or spaceName to disambiguate.")

        ws = _resolve_workspace(workspaceId)
        if not ws:
            op = {
                "id": _new_op_id(), "workspace_id": workspaceId, "tool_name": "get_folder", "operation_type": "read",
                "request_params": {"workspaceId": workspaceId, "folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
                "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
                "status": "failed", "error_message": "Workspace not found.",
                "started_at": now, "finished_at": now, "created_at": now, "updated_at": now
            }
            _log(op)
            return _err("NOT_FOUND", "Workspace not found.", workspaceId=workspaceId)

        # read allowed even if read_only/disabled? business rules: disabled rejects write; read_only only read proceeds; disabled does not say read disallowed.
        # We'll allow read in all statuses.
        op_id = _new_op_id()
        op = {
            "id": op_id, "workspace_id": workspaceId, "tool_name": "get_folder", "operation_type": "read",
            "request_params": {"workspaceId": workspaceId, "folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
            "resolved_clickup_ids": None, "bulk_count": None, "succeeded_count": None, "failed_count": None,
            "status": "in_progress", "error_message": None,
            "started_at": now, "finished_at": None, "created_at": now, "updated_at": now
        }

        resolved_map = {}
        space = None
        scoped_space_clickup_id = None
        if folderId is None and folderName is not None:
            space, smap = _resolve_space_by_id_or_name(workspaceId, clickup_space_id=spaceId, space_name=spaceName)
            if space == "AMBIGUOUS":
                op["status"] = "rejected"
                op["error_message"] = "Ambiguous spaceName; provide spaceId."
                op["resolved_clickup_ids"] = smap
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["updated_at"] = op["finished_at"]
                _log(op)
                return _err("CONFLICT", "Ambiguous spaceName; provide spaceId.", **(smap or {}))
            if not space:
                op["status"] = "failed"
                op["error_message"] = "Space not found."
                op["resolved_clickup_ids"] = smap
                op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                op["updated_at"] = op["finished_at"]
                _log(op)
                return _err("NOT_FOUND", "Space not found.", spaceId=spaceId, spaceName=spaceName)
            scoped_space_clickup_id = space.get("clickup_id")
            resolved_map.update(smap or {})

        folder, fmap = _resolve_folder(workspaceId, clickup_folder_id=folderId, folder_name=folderName, scoped_space_clickup_id=scoped_space_clickup_id)
        if folder == "AMBIGUOUS":
            op["status"] = "rejected"
            op["error_message"] = "Ambiguous folderName within space scope; provide folderId."
            op["resolved_clickup_ids"] = {**resolved_map, **(fmap or {})}
            op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op["updated_at"] = op["finished_at"]
            _log(op)
            return _err("CONFLICT", "Ambiguous folderName within space scope; provide folderId.", **(fmap or {}))
        if not folder:
            op["status"] = "failed"
            op["error_message"] = "Folder not found."
            op["resolved_clickup_ids"] = {**resolved_map, **(fmap or {})} if (resolved_map or fmap) else None
            op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op["updated_at"] = op["finished_at"]
            _log(op)
            return _err("NOT_FOUND", "Folder not found.", folderId=folderId, folderName=folderName)

        # Build hierarchy context: space + lists under folder
        entities = _load("hierarchy_entities.json")
        space_entity = None
        if folder.get("parent_entity_id"):
            for e in entities:
                if e.get("id") == folder.get("parent_entity_id"):
                    space_entity = e
                    break
        # lists in folder: those whose parent_entity_id == folder.id
        lists_in_folder = [
            e for e in entities
            if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list" and e.get("parent_entity_id") == folder.get("id") and e.get("status") != "deleted"
        ]

        op["status"] = "succeeded"
        op["resolved_clickup_ids"] = {**resolved_map, **(fmap or {})} if (resolved_map or fmap) else None
        op["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["updated_at"] = op["finished_at"]
        _log(op)

        latency_ms = int((time.time() - t0) * 1000)
        return {
            "folder": folder,
            "context": {
                "space": {"id": space_entity.get("id"), "clickup_id": space_entity.get("clickup_id"), "name": space_entity.get("name")} if space_entity else None,
                "lists": lists_in_folder
            },
            "workspace_id": workspaceId,
            "latency_ms": latency_ms
        }
    except Exception as e:
        op = {
            "id": _new_op_id(),
            "workspace_id": workspaceId if isinstance(workspaceId, str) else "unknown",
            "tool_name": "get_folder",
            "operation_type": "read",
            "request_params": {"workspaceId": workspaceId, "folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
