def update_folder(workspaceId, folderId=None, folderName=None, spaceId=None, spaceName=None, name=None, override_statuses=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ops = _load("integration_operations.json")
    op_id = "op_" + uuid.uuid4().hex
    op_row = {
        "id": op_id,
        "workspace_id": workspaceId,
        "tool_name": "update_folder",
        "operation_type": "write",
        "request_params": {
            "workspaceId": workspaceId, "folderId": folderId, "folderName": folderName,
            "spaceId": spaceId, "spaceName": spaceName, "name": name, "override_statuses": override_statuses
        },
        "resolved_clickup_ids": None,
        "bulk_count": None,
        "succeeded_count": None,
        "failed_count": None,
        "status": "received",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("integration_operations.json", ops)

    def _finalize(status, error_message=None, resolved=None, succeeded_count=None, failed_count=None):
        ops2 = _load("integration_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                if r.get("started_at") is None:
                    r["started_at"] = r["updated_at"]
                r["finished_at"] = r["updated_at"]
                r["status"] = status
                r["error_message"] = error_message
                r["resolved_clickup_ids"] = resolved
                r["succeeded_count"] = succeeded_count
                r["failed_count"] = failed_count
                break
        _save("integration_operations.json", ops2)

    # Validate basic inputs
    if not isinstance(workspaceId, str) or not workspaceId:
        _finalize("rejected", "workspaceId must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspaceId must be a non-empty string")
    if not workspaceId.startswith("cu_wsp_"):
        _finalize("rejected", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")

    if folderId is None and folderName is None:
        _finalize("rejected", "Provide folderId or folderName")
        return _err("VALIDATION_ERROR", "Provide folderId or folderName")
    if folderId is not None and (not isinstance(folderId, str) or not folderId):
        _finalize("rejected", "folderId must be a non-empty string")
        return _err("VALIDATION_ERROR", "folderId must be a non-empty string")
    if folderName is not None and (not isinstance(folderName, str) or not folderName.strip()):
        _finalize("rejected", "folderName must be a non-empty string")
        return _err("VALIDATION_ERROR", "folderName must be a non-empty string")
    if folderId is None:
        # Name-based folder resolution requires space scope
        if spaceId is None and spaceName is None:
            _finalize("rejected", "folderName resolution requires spaceId or spaceName")
            return _err("VALIDATION_ERROR", "folderName resolution requires spaceId or spaceName")

    # Must provide at least one updatable field
    if name is None and override_statuses is None:
        _finalize("rejected", "No updatable fields provided; supply name and/or override_statuses")
        return _err("VALIDATION_ERROR", "No updatable fields provided; supply name and/or override_statuses")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _finalize("rejected", "name must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if override_statuses is not None and not isinstance(override_statuses, bool):
        _finalize("rejected", "override_statuses must be boolean when provided")
        return _err("VALIDATION_ERROR", "override_statuses must be boolean when provided")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws:
        _finalize("failed", "Unknown workspaceId")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") == "disabled":
        _finalize("rejected", "Workspace is disabled; write operations are not allowed")
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations")
    if ws.get("status") == "read_only":
        _finalize("rejected", "Workspace is read_only; write operations are not allowed")
        return _err("UNAUTHORIZED", "Workspace is read-only for write operations")

    entities = _load("hierarchy_entities.json")

    def _resolve_space_clickup_id():
        if spaceId is not None:
            if not isinstance(spaceId, str) or not spaceId:
                return (None, _err("VALIDATION_ERROR", "spaceId must be a non-empty string"))
            space = next((e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "space" and e.get("clickup_id") == spaceId and e.get("status") != "deleted"), None)
            if not space:
                return (None, _err("NOT_FOUND", "Space not found"))
            return (space.get("clickup_id"), None)
        if spaceName is not None:
            if not isinstance(spaceName, str) or not spaceName.strip():
                return (None, _err("VALIDATION_ERROR", "spaceName must be a non-empty string"))
            matches = [e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "space" and e.get("name") == spaceName and e.get("status") != "deleted"]
            if len(matches) == 0:
                return (None, _err("NOT_FOUND", "Space not found"))
            if len(matches) > 1:
                return (None, _err("CONFLICT", "Ambiguous spaceName; multiple spaces match", matches=[m.get("clickup_id") for m in matches]))
            return (matches[0].get("clickup_id"), None)
        return (None, None)

    resolved = {}

    # Resolve folder entity
    folder = None
    if folderId is not None:
        folder = next((e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "folder" and e.get("clickup_id") == folderId), None)
        if not folder or folder.get("status") == "deleted":
            _finalize("failed", "Folder not found", resolved={"folderId": folderId})
            return _err("NOT_FOUND", "Folder not found")
        resolved["folderClickupId"] = folder.get("clickup_id")
    else:
        space_clickup_id, space_err = _resolve_space_clickup_id()
        if space_err:
            _finalize("failed" if space_err["error"]["code"] != "VALIDATION_ERROR" else "rejected", space_err["error"]["message"])
            return space_err
        resolved["spaceClickupId"] = space_clickup_id
        # Find active folders in the scoped space by name
        matches = [e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "folder" and e.get("status") == "active" and e.get("name") == folderName and e.get("space_clickup_id") == space_clickup_id]
        if len(matches) == 0:
            _finalize("failed", "Folder not found", resolved={"spaceClickupId": space_clickup_id, "folderName": folderName})
            return _err("NOT_FOUND", "Folder not found")
        if len(matches) > 1:
            # Still ambiguous even with space scope (possible duplicates)
            _finalize("rejected", "Ambiguous folderName within space; multiple folders match", resolved={"spaceClickupId": space_clickup_id, "folderName": folderName})
            return _err("CONFLICT", "Ambiguous folderName within space; multiple folders match", matches=[m.get("clickup_id") for m in matches])
        folder = matches[0]
        resolved["folderClickupId"] = folder.get("clickup_id")

    # Update allowed fields only
    updated = False
    if name is not None:
        folder["name"] = name
        updated = True
    if override_statuses is not None:
        folder["override_statuses"] = override_statuses
        updated = True

    if not updated:
        _finalize("rejected", "No changes to apply", resolved=resolved)
        return _err("VALIDATION_ERROR", "No changes to apply")

    folder["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Persist
    for i, e in enumerate(entities):
        if e.get("id") == folder.get("id"):
            entities[i] = folder
            break
    _save("hierarchy_entities.json", entities)

    _finalize("succeeded", None, resolved=resolved)
    return {"folder": folder, "operation": {"id": op_id, "status": "succeeded", "latency_ms": int((time.time() - t0) * 1000)}}

def delete_folder(workspaceId, folderId=None, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []
    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")

    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "delete_folder",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "folderId": folderId, "folderName": folderName, "spaceId": spaceId, "spaceName": spaceName},
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    # Validate identifiers
    if (folderId is None or (isinstance(folderId, str) and not folderId.strip())) and (folderName is None or (isinstance(folderName, str) and not folderName.strip())):
        _op_write("rejected", "Either folderId or folderName is required", resolved=None)
        return _err("VALIDATION_ERROR", "Either folderId or folderName is required", field="folderId")

    ents = _rows(_load("hierarchy_entities.json"))
    target = None
    resolved = {}

    if folderId is not None and isinstance(folderId, str) and folderId.strip():
        fid = folderId.strip()
        for e in ents:
            if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "folder" and (e.get("id") == fid or e.get("clickup_id") == fid):
                target = e
                break
        resolved["folderId"] = fid

    if target is None:
        fname = folderName.strip() if isinstance(folderName, str) else ""
        # folderName requires space scope
        if (spaceId is None or (isinstance(spaceId, str) and not spaceId.strip())) and (spaceName is None or (isinstance(spaceName, str) and not spaceName.strip())):
            _op_write("rejected", "spaceId or spaceName is required to resolve folderName", resolved={"folderName": fname})
            return _err("VALIDATION_ERROR", "spaceId or spaceName is required to resolve folderName", field="spaceId")

        # resolve space
        space_ent = None
        if spaceId is not None and isinstance(spaceId, str) and spaceId.strip():
            sid = spaceId.strip()
            for e in ents:
                if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and (e.get("id") == sid or e.get("clickup_id") == sid):
                    space_ent = e
                    break
            resolved["spaceId"] = sid
        if space_ent is None:
            sname = spaceName.strip() if isinstance(spaceName, str) else ""
            sm = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("status") == "active" and e.get("name") == sname]
            if len(sm) == 0:
                _op_write("failed", "Space not found", resolved={"spaceName": sname, "folderName": fname})
                return _err("NOT_FOUND", "Space not found", field="spaceName")
            if len(sm) > 1:
                _op_write("rejected", "spaceName is ambiguous; provide spaceId", resolved={"spaceName": sname, "matchCount": len(sm)})
                return _err("CONFLICT", "spaceName is ambiguous; provide spaceId", field="spaceName", matchCount=len(sm))
            space_ent = sm[0]
            resolved["spaceName"] = sname

        fm = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "folder" and e.get("status") == "active" and e.get("name") == fname and e.get("parent_entity_id") == space_ent.get("id")]
        if len(fm) == 0:
            _op_write("failed", "Folder not found", resolved={**resolved, "folderName": fname})
            return _err("NOT_FOUND", "Folder not found", field="folderName")
        if len(fm) > 1:
            _op_write("rejected", "folderName is ambiguous within space; provide folderId", resolved={**resolved, "folderName": fname, "matchCount": len(fm)})
            return _err("CONFLICT", "folderName is ambiguous within space; provide folderId", field="folderName", matchCount=len(fm))
        target = fm[0]
        resolved["folderName"] = fname

    if target.get("status") == "deleted":
        _op_write("succeeded", None, resolved={**resolved, "folderEntityId": target.get("id")})
        return {"deleted": True, "folder": target, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

    # Delete folder -> delete lists under it -> delete tasks under those lists
    now = _now()
    target["status"] = "deleted"
    target["archived"] = True
    target["updated_at"] = now
    raw = target.get("raw") if isinstance(target.get("raw"), dict) else {}
    raw["deleted_via"] = "integration_mirror"
    raw["deleted_at"] = now
    target["raw"] = raw

    folder_entity_id = target.get("id")
    # Find lists whose parent is this folder
    list_ids = [e.get("id") for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("parent_entity_id") == folder_entity_id and e.get("status") != "deleted"]
    for e in ents:
        if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("parent_entity_id") == folder_entity_id and e.get("status") != "deleted":
            e["status"] = "deleted"
            e["archived"] = True
            e["updated_at"] = now
            e_raw = e.get("raw") if isinstance(e.get("raw"), dict) else {}
            e_raw["deleted_via"] = "integration_mirror:folder_deleted"
            e_raw["deleted_at"] = now
            e["raw"] = e_raw

    tasks_rows = _rows(_load("tasks.json"))
    for tr in tasks_rows:
        if isinstance(tr, dict) and tr.get("workspace_id") == ws_id and tr.get("list_entity_id") in set(list_ids) and tr.get("status") != "deleted":
            tr["status"] = "deleted"
            tr["updated_at"] = now
            tr_raw = tr.get("raw") if isinstance(tr.get("raw"), dict) else {}
            tr_raw["deleted_via"] = "integration_mirror:folder_deleted"
            tr_raw["deleted_at"] = now
            tr["raw"] = tr_raw

    _save("hierarchy_entities.json", ents)
    _save("tasks.json", tasks_rows)

    _op_write("succeeded", None, resolved={**resolved, "folderEntityId": target.get("id")})
    return {"deleted": True, "folder": target, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def get_space_tags(workspaceId, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ops = _load("integration_operations.json")
    op_id = "op_" + uuid.uuid4().hex
    op_row = {
        "id": op_id,
        "workspace_id": workspaceId,
        "tool_name": "get_space_tags",
        "operation_type": "read",
        "request_params": {"workspaceId": workspaceId, "spaceId": spaceId, "spaceName": spaceName},
        "resolved_clickup_ids": None,
        "bulk_count": None,
        "succeeded_count": None,
        "failed_count": None,
        "status": "received",
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("integration_operations.json", ops)

    def _finalize(status, error_message=None, resolved=None):
        ops2 = _load("integration_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                if r.get("started_at") is None:
                    r["started_at"] = r["updated_at"]
                r["finished_at"] = r["updated_at"]
                r["status"] = status
                r["error_message"] = error_message
                r["resolved_clickup_ids"] = resolved
                break
        _save("integration_operations.json", ops2)

    if not isinstance(workspaceId, str) or not workspaceId:
        _finalize("rejected", "workspaceId must be a non-empty string")
        return _err("VALIDATION_ERROR", "workspaceId must be a non-empty string")
    if not workspaceId.startswith("cu_wsp_"):
        _finalize("rejected", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]+$")

    if spaceId is None and spaceName is None:
        _finalize("rejected", "Provide spaceId or spaceName")
        return _err("VALIDATION_ERROR", "Provide spaceId or spaceName")
    if spaceId is not None and (not isinstance(spaceId, str) or not spaceId):
        _finalize("rejected", "spaceId must be a non-empty string")
        return _err("VALIDATION_ERROR", "spaceId must be a non-empty string")
    if spaceName is not None and (not isinstance(spaceName, str) or not spaceName.strip()):
        _finalize("rejected", "spaceName must be a non-empty string")
        return _err("VALIDATION_ERROR", "spaceName must be a non-empty string")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws:
        _finalize("failed", "Unknown workspaceId")
        return _err("NOT_FOUND", "Workspace not found")
    # read tools allowed even in read_only; disabled treated as unauthorized
    if ws.get("status") == "disabled":
        _finalize("rejected", "Workspace is disabled")
        return _err("UNAUTHORIZED", "Workspace is disabled")

    entities = _load("hierarchy_entities.json")

    resolved = {}
    space = None
    if spaceId is not None:
        space = next((e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "space" and e.get("clickup_id") == spaceId and e.get("status") != "deleted"), None)
        if not space:
            _finalize("failed", "Space not found", resolved={"spaceId": spaceId})
            return _err("NOT_FOUND", "Space not found")
        resolved["spaceClickupId"] = space.get("clickup_id")
    else:
        matches = [e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "space" and e.get("name") == spaceName and e.get("status") != "deleted"]
        if len(matches) == 0:
            _finalize("failed", "Space not found", resolved={"spaceName": spaceName})
            return _err("NOT_FOUND", "Space not found")
        if len(matches) > 1:
            _finalize("failed", "Ambiguous spaceName; multiple spaces match", resolved={"spaceName": spaceName})
            return _err("CONFLICT", "Ambiguous spaceName; multiple spaces match", matches=[m.get("clickup_id") for m in matches])
        space = matches[0]
        resolved["spaceClickupId"] = space.get("clickup_id")

    # Tags derived primarily from space.raw.tags; fallback infer from tasks in space
    tags = []
    raw = space.get("raw") if isinstance(space.get("raw"), dict) else None
    if raw and isinstance(raw.get("tags"), list):
        # Accept either list of strings or list of objects with 'name'
        for t in raw.get("tags"):
            if isinstance(t, str):
                tags.append({"name": t})
            elif isinstance(t, dict):
                nm = t.get("name")
                if isinstance(nm, str) and nm:
                    tags.append(t)
    # Fallback: infer from tasks.tag_names in this space if no explicit tag list
    if not tags:
        tasks = _load("tasks.json")
        # find lists in this space
        space_clickup_id = space.get("clickup_id")
        list_internal_ids = {e.get("id") for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list" and e.get("status") != "deleted" and e.get("space_clickup_id") == space_clickup_id}
        seen = set()
        for tk in tasks:
            if tk.get("workspace_id") != workspaceId or tk.get("status") != "active":
                continue
            if tk.get("list_entity_id") not in list_internal_ids:
                continue
            tn = tk.get("tag_names")
            if isinstance(tn, list):
                for nm in tn:
                    if isinstance(nm, str) and nm and nm not in seen:
                        seen.add(nm)
                        tags.append({"name": nm})

    _finalize("succeeded", None, resolved=resolved)
    return {
        "space": {"id": space.get("id"), "clickup_id": space.get("clickup_id"), "name": space.get("name")},
        "tags": tags,
        "operation": {"id": op_id, "status": "succeeded", "latency_ms": int((time.time() - t0) * 1000)}
    }

def add_tag_to_task(workspaceId, tagName, taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _rows(d):
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return d if isinstance(d, list) else []
    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:20].upper()

    t0 = time.time()
    started_at = _now()

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        return _err("VALIDATION_ERROR", "workspaceId is required", field="workspaceId")
    if not isinstance(tagName, str) or not tagName.strip():
        return _err("VALIDATION_ERROR", "tagName is required", field="tagName")

    ws_lookup = workspaceId.strip()
    workspaces = _rows(_load("workspaces.json"))
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and (w.get("id") == ws_lookup or w.get("clickup_team_id") == ws_lookup):
            ws = w
            break
    ws_id = ws.get("id") if isinstance(ws, dict) else None

    op_id = _gen_id("cu_op_")

    def _op_write(status_val, error_message=None, resolved=None):
        finished_at = _now()
        ops = _rows(_load("integration_operations.json"))
        ops.append({
            "id": op_id,
            "workspace_id": ws_id or ws_lookup or "unknown",
            "tool_name": "add_tag_to_task",
            "operation_type": "write",
            "request_params": {"workspaceId": workspaceId, "taskId": taskId, "taskName": taskName, "listName": listName, "tagName": tagName},
            "resolved_clickup_ids": resolved,
            "bulk_count": None,
            "succeeded_count": None,
            "failed_count": None,
            "status": status_val,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": started_at,
            "updated_at": finished_at,
        })
        _save("integration_operations.json", ops)

    if ws is None or not ws_id:
        _op_write("failed", "Workspace not found", resolved=None)
        return _err("NOT_FOUND", "Workspace not found", field="workspaceId")

    if ws.get("status") == "disabled":
        _op_write("rejected", "Workspace is disabled; write operations are not allowed", resolved=None)
        return _err("UNAUTHORIZED", "Workspace is disabled for write operations", field="workspaceId")

    tasks_rows = _rows(_load("tasks.json"))
    ents = _rows(_load("hierarchy_entities.json"))
    resolved = {}

    # Resolve task
    target = None
    if taskId is not None and isinstance(taskId, str) and taskId.strip():
        tid = taskId.strip()
        for tr in tasks_rows:
            if not isinstance(tr, dict):
                continue
            if tr.get("workspace_id") != ws_id:
                continue
            if tr.get("status") != "active":
                continue
            if tr.get("id") == tid or tr.get("clickup_task_id") == tid or (tr.get("custom_id") and tr.get("custom_id") == tid):
                target = tr
                break
        resolved["taskId"] = tid

    if target is None:
        if not isinstance(taskName, str) or not taskName.strip():
            _op_write("rejected", "Either taskId or taskName is required", resolved=resolved or None)
            return _err("VALIDATION_ERROR", "Either taskId or taskName is required", field="taskId")
        tname = taskName.strip()
        candidates = [tr for tr in tasks_rows if isinstance(tr, dict) and tr.get("workspace_id") == ws_id and tr.get("status") == "active" and tr.get("name") == tname]
        resolved["taskName"] = tname
        if listName is not None and isinstance(listName, str) and listName.strip():
            lname = listName.strip()
            lists = [e for e in ents if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "list" and e.get("status") == "active" and e.get("name") == lname]
            if len(lists) == 0:
                _op_write("failed", "List not found for listName", resolved={**resolved, "listName": lname})
                return _err("NOT_FOUND", "List not found for listName", field="listName")
            if len(lists) > 1:
                _op_write("rejected", "listName is ambiguous; provide taskId", resolved={**resolved, "listName": lname, "matchCount": len(lists)})
                return _err("CONFLICT", "listName is ambiguous; provide taskId", field="listName", matchCount=len(lists))
            list_entity_id = lists[0].get("id")
            candidates = [tr for tr in candidates if tr.get("list_entity_id") == list_entity_id]
            resolved.update({"listName": lname, "listEntityId": list_entity_id})
        if len(candidates) == 0:
            _op_write("failed", "Task not found", resolved=resolved or None)
            return _err("NOT_FOUND", "Task not found", field="taskName")
        if len(candidates) > 1:
            _op_write("rejected", "taskName is ambiguous; provide taskId or include listName", resolved={**resolved, "matchCount": len(candidates)})
            return _err("CONFLICT", "taskName is ambiguous; provide taskId or include listName", field="taskName", matchCount=len(candidates))
        target = candidates[0]

    # Verify tag exists in the task's space
    # Determine space entity id by walking list->parent (folder or space) -> space
    list_entity_id = target.get("list_entity_id")
    list_ent = None
    for e in ents:
        if isinstance(e, dict) and e.get("id") == list_entity_id and e.get("workspace_id") == ws_id:
            list_ent = e
            break
    if list_ent is None:
        _op_write("failed", "Task list not found in hierarchy cache", resolved={**resolved, "listEntityId": list_entity_id})
        return _err("NOT_FOUND", "Task list not found in hierarchy cache", field="listName")

    space_entity = None
    # Prefer space_clickup_id to identify the space; else walk parent_entity_id chain
    if list_ent.get("space_clickup_id"):
        for e in ents:
            if isinstance(e, dict) and e.get("workspace_id") == ws_id and e.get("entity_type") == "space" and e.get("clickup_id") == list_ent.get("space_clickup_id"):
                space_entity = e
                break
    if space_entity is None:
        # walk up parents
        pid = list_ent.get("parent_entity_id")
        seen = set()
        while pid and pid not in seen:
            seen.add(pid)
            pe = next((x for x in ents if isinstance(x, dict) and x.get("workspace_id") == ws_id and x.get("id") == pid), None)
            if not pe:
                break
            if pe.get("entity_type") == "space":
                space_entity = pe
                break
            pid = pe.get("parent_entity_id")

    if space_entity is None:
        _op_write("failed", "Could not resolve space for task", resolved={**resolved, "listEntityId": list_ent.get("id")})
        return _err("NOT_FOUND", "Could not resolve space for task", field="workspaceId")

    # tags definition: from space.raw.tags (if present) and/or inferred from tasks.tag_names
    wanted = tagName.strip()
    known = set()

    raw = space_entity.get("raw")
    if isinstance(raw, dict):
        tags_def = raw.get("tags") or raw.get("tag_names") or raw.get("space_tags")
        if isinstance(tags_def, list):
            for t in tags_def:
                if isinstance(t, str):
                    known.add(t)
                elif isinstance(t, dict) and isinstance(t.get("name"), str):
                    known.add(t["name"])
    # infer from tasks in same space
    space_clickup_id = space_entity.get("clickup_id")
    for tr in tasks_rows:
        if not isinstance(tr, dict) or tr.get("workspace_id") != ws_id or tr.get("status") != "active":
            continue
        le = next((x for x in ents if isinstance(x, dict) and x.get("workspace_id") == ws_id and x.get("id") == tr.get("list_entity_id")), None)
        if le and le.get("space_clickup_id") == space_clickup_id:
            tnames = tr.get("tag_names")
            if isinstance(tnames, list):
                for tn in tnames:
                    if isinstance(tn, str):
                        known.add(tn)

    if wanted not in known:
        _op_write("failed", "Tag does not exist in the target space", resolved={**resolved, "spaceEntityId": space_entity.get("id"), "tagName": wanted})
        return _err("NOT_FOUND", "Tag does not exist in the target space", field="tagName", spaceEntityId=space_entity.get("id"))

    # Mutate association (idempotent)
    current = target.get("tag_names")
    if not isinstance(current, list):
        current = []
    if wanted not in current:
        current = current + [wanted]
        target["tag_names"] = current
        target["updated_at"] = _now()

        # Add activity row
        now = _now()
        activity_rows = _rows(_load("task_activity.json"))
        new_act = {
            "id": _gen_id("cu_act_"),
            "workspace_id": ws_id,
            "task_id": target.get("id"),
            "activity_type": "tag_added",
            "clickup_comment_id": None,
            "comment_text": None,
            "comment_assignee_clickup_user_id": None,
            "comment_notify_all": None,
            "attachment_clickup_file_id": None,
            "attachment_filename": None,
            "attachment_source_type": None,
            "attachment_url": None,
            "tag_space_entity_id": space_entity.get("id"),
            "tag_name": wanted,
            "cursor_id": None,
            "occurred_at": now,
            "status": "active",
            "raw": {"created_via": "integration_mirror"},
            "created_at": now,
            "updated_at": now,
        }
        activity_rows.append(new_act)
        _save("task_activity.json", activity_rows)

        _save("tasks.json", tasks_rows)
        _op_write("succeeded", None, resolved={**resolved, "taskRowId": target.get("id"), "spaceEntityId": space_entity.get("id"), "tagName": wanted})
        return {"task": target, "added": True, "tagName": wanted, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

    # already present: still record operation, but no mutation (idempotent). However contract says "NO SUCCESS WITHOUT EFFECT" for mutations.
    # We'll treat idempotent add as success with effect=false but still a real semantics; to comply, write an activity only if ClickUp would.
    # Here we choose to be idempotent without adding a duplicate activity row; return a conflict instead would be wrong.
    _op_write("succeeded", None, resolved={**resolved, "taskRowId": target.get("id"), "spaceEntityId": space_entity.get("id"), "tagName": wanted, "idempotent": True})
    return {"task": target, "added": False, "tagName": wanted, "operation_id": op_id, "latency_ms": int((time.time() - t0) * 1000)}

def remove_tag_from_task(workspaceId, tagName, taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0509000" if __import__("os").path.isdir("./environment_mix/0509000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- helpers ---
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:18].upper()}"

    def _record_op(workspace_id, tool_name, op_type, request_params, status, error_message=None, resolved=None, bulk=None, succ=None, fail=None, started_at=None, finished_at=None):
        ops = _load("integration_operations.json")
        op = {
            "id": _new_id("op"),
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "operation_type": op_type,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "resolved_clickup_ids": resolved,
            "bulk_count": bulk,
            "succeeded_count": succ,
            "failed_count": fail,
            "status": status,
            "error_message": error_message,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("integration_operations.json", ops)
        return op

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _parse_workspace_pk(x):
        if not _is_nonempty_str(x):
            return False
        return re.match(r"^cu_wsp_[0-9A-Z]{3,}$", x) is not None

    def _parse_task_pk(x):
        if not _is_nonempty_str(x):
            return False
        return re.match(r"^cu_tsk_[0-9A-Z]{3,}$", x) is not None

    # --- validate inputs ---
    if not _parse_workspace_pk(workspaceId):
        _record_op(workspaceId if isinstance(workspaceId, str) else "unknown", "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "rejected", "Invalid workspaceId format")
        return _err("VALIDATION_ERROR", "Invalid workspaceId format", field="workspaceId")

    if not _is_nonempty_str(tagName):
        _record_op(workspaceId, "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "rejected", "tagName is required")
        return _err("VALIDATION_ERROR", "tagName is required", field="tagName")

    if taskId is None and taskName is None:
        _record_op(workspaceId, "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "rejected", "Either taskId or taskName is required")
        return _err("VALIDATION_ERROR", "Either taskId or taskName is required", field="taskId|taskName")

    if taskId is not None and not _parse_task_pk(taskId):
        _record_op(workspaceId, "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "rejected", "Invalid taskId format")
        return _err("VALIDATION_ERROR", "Invalid taskId format", field="taskId")

    if taskName is not None and not _is_nonempty_str(taskName):
        _record_op(workspaceId, "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "rejected", "taskName must be a non-empty string")
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string", field="taskName")

    if listName is not None and (not isinstance(listName, str) or listName.strip() == ""):
        _record_op(workspaceId, "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "rejected", "listName must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided", field="listName")

    # --- resolve ambient auth / workspace prerequisites ---
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws:
        _record_op(workspaceId, "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "failed", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)

    # enforce workspace write policy
    if ws.get("status") in ("disabled", "read_only"):
        _record_op(workspaceId, "remove_tag_from_task", "write",
                   {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                   "rejected", f"Workspace is {ws.get('status')} and does not allow write operations")
        return _err("UNAUTHORIZED", "Workspace does not allow write operations", workspace_status=ws.get("status"))

    # --- create op row (received -> in_progress) ---
    op = _record_op(workspaceId, "remove_tag_from_task", "write",
                    {"workspaceId": workspaceId, "tagName": tagName, "taskId": taskId, "taskName": taskName, "listName": listName},
                    "received", started_at=now)
    ops = _load("integration_operations.json")
    # transition to in_progress (legal: received -> in_progress)
    for row in ops:
        if row.get("id") == op["id"]:
            row["status"] = "in_progress"
            row["started_at"] = now
            row["updated_at"] = now
            break
    _save("integration_operations.json", ops)

    # --- resolve task ---
    tasks = _load("tasks.json")
    hierarchy = _load("hierarchy_entities.json")

    resolved = {}

    def _finish(status, error_message=None, resolved_obj=None):
        ops2 = _load("integration_operations.json")
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        # transition rules: in_progress -> succeeded/failed
        for row in ops2:
            if row.get("id") == op["id"]:
                row["status"] = status
                row["error_message"] = error_message
                row["resolved_clickup_ids"] = resolved_obj
                row["finished_at"] = finished
                row["updated_at"] = finished
                break
        _save("integration_operations.json", ops2)
        return finished

    task = None
    if taskId is not None:
        task = next((t for t in tasks if t.get("id") == taskId and t.get("workspace_id") == workspaceId), None)
        if not task:
            _finish("failed", "Task not found", resolved)
            return _err("NOT_FOUND", "Task not found", taskId=taskId)
        if task.get("status") != "active":
            _finish("failed", "Task is deleted", {"taskId": taskId})
            return _err("NOT_FOUND", "Task not found", taskId=taskId)
        resolved["taskId"] = taskId
        resolved["clickupTaskId"] = task.get("clickup_task_id")
    else:
        # name-based resolution must be scoped to a list (business rule)
        if listName is None:
            _finish("rejected", "taskName resolution requires listName scoping for this endpoint", resolved)
            return _err("VALIDATION_ERROR", "taskName resolution requires listName to disambiguate", field="listName")

        # resolve list by name uniquely within workspace (active lists only)
        candidate_lists = [e for e in hierarchy
                           if e.get("workspace_id") == workspaceId
                           and e.get("entity_type") == "list"
                           and e.get("status") == "active"
                           and isinstance(e.get("name"), str)
                           and e.get("name") == listName]
        if len(candidate_lists) == 0:
            _finish("failed", "List not found", {"listName": listName})
            return _err("NOT_FOUND", "List not found", listName=listName)
        if len(candidate_lists) > 1:
            _finish("rejected", "Ambiguous listName in workspace; provide listId instead", {"listName": listName})
            return _err("CONFLICT", "Ambiguous listName in workspace; provide listId instead", listName=listName, matches=len(candidate_lists))

        list_entity = candidate_lists[0]
        resolved["listName"] = listName
        resolved["listEntityId"] = list_entity.get("id")
        resolved["listClickupId"] = list_entity.get("clickup_id")

        candidates = [t for t in tasks
                      if t.get("workspace_id") == workspaceId
                      and t.get("status") == "active"
                      and t.get("list_entity_id") == list_entity.get("id")
                      and isinstance(t.get("name"), str)
                      and t.get("name") == taskName]
        if len(candidates) != 1:
            _finish("rejected", "taskName did not resolve uniquely within the scoped list", {"taskName": taskName, **resolved})
            return _err("CONFLICT", "taskName did not resolve uniquely within the scoped list", taskName=taskName, matches=len(candidates))
        task = candidates[0]
        resolved["taskName"] = taskName
        resolved["taskId"] = task.get("id")
        resolved["clickupTaskId"] = task.get("clickup_task_id")

    # --- verify tag exists in the task's space ---
    # find list entity -> parent chain -> space
    list_entity = next((e for e in hierarchy if e.get("id") == task.get("list_entity_id") and e.get("workspace_id") == workspaceId), None)
    if not list_entity or list_entity.get("entity_type") != "list" or list_entity.get("status") == "deleted":
        _finish("failed", "Task list is missing or deleted", resolved)
        return _err("CONFLICT", "Task list is missing or deleted", list_entity_id=task.get("list_entity_id"))

    space_clickup_id = list_entity.get("space_clickup_id")
    space_entity = None
    if isinstance(space_clickup_id, str):
        space_entity = next((e for e in hierarchy
                             if e.get("workspace_id") == workspaceId and e.get("entity_type") == "space"
                             and e.get("clickup_id") == space_clickup_id and e.get("status") == "active"), None)
    if not space_entity:
        # fall back: walk parents
        parents = {e.get("id"): e for e in hierarchy if e.get("workspace_id") == workspaceId}
        cur = list_entity
        guard = 0
        while cur and cur.get("parent_entity_id") and guard < 10:
            guard += 1
            cur = parents.get(cur.get("parent_entity_id"))
        if cur and cur.get("entity_type") == "space" and cur.get("status") == "active":
            space_entity = cur

    if not space_entity:
        _finish("failed", "Could not resolve task space to verify tag", resolved)
        return _err("CONFLICT", "Could not resolve task space to verify tag")

    resolved["spaceEntityId"] = space_entity.get("id")
    resolved["spaceClickupId"] = space_entity.get("clickup_id")

    # determine known tags in space
    known_tags = set()
    raw = space_entity.get("raw")
    if isinstance(raw, dict):
        tags = raw.get("tags")
        if isinstance(tags, list):
            for t in tags:
                if isinstance(t, dict) and isinstance(t.get("name"), str):
                    known_tags.add(t["name"])
                elif isinstance(t, str):
                    known_tags.add(t)
    # also infer from tasks in this workspace that belong to this space
    space_list_ids = set(e.get("id") for e in hierarchy
                         if e.get("workspace_id") == workspaceId and e.get("entity_type") == "list"
                         and e.get("status") == "active"
                         and (e.get("space_clickup_id") == space_entity.get("clickup_id")))
    for t in tasks:
        if t.get("workspace_id") == workspaceId and t.get("status") == "active" and t.get("list_entity_id") in space_list_ids:
            tn = t.get("tag_names")
            if isinstance(tn, list):
                for nm in tn:
                    if isinstance(nm, str):
                        known_tags.add(nm)

    if tagName not in known_tags:
        _finish("failed", "Tag does not exist in the target space", {**resolved, "tagName": tagName})
        return _err("NOT_FOUND", "Tag does not exist in the target space", tagName=tagName)

    # --- mutate: remove tag association (idempotent) and add activity row ---
    existing_tags = task.get("tag_names")
    if not isinstance(existing_tags, list):
        existing_tags = []
    # normalize to unique, preserve order
    seen = set()
    normalized = []
    for nm in existing_tags:
        if isinstance(nm, str) and nm not in seen:
            seen.add(nm)
            normalized.append(nm)

    had_tag = tagName in seen
    if had_tag:
        normalized = [nm for nm in normalized if nm != tagName]
        task["tag_names"] = normalized
        task["updated_at"] = now

    # Always write an activity row for explicit remove request (even if idempotent/no-op)
    activity = _load("task_activity.json")
    act_row = {
        "id": _new_id("act"),
        "workspace_id": workspaceId,
        "task_id": task.get("id"),
        "activity_type": "tag_removed",
        "clickup_comment_id": None,
        "comment_text": None,
        "comment_assignee_clickup_user_id": None,
        "comment_notify_all": None,
        "attachment_clickup_file_id": None,
        "attachment_filename": None,
        "attachment_source_type": None,
        "attachment_url": None,
        "tag_space_entity_id": space_entity.get("id"),
        "tag_name": tagName,
        "cursor_id": None,
        "occurred_at": now,
        "status": "active",
        "raw": {"idempotent_noop": (not had_tag)},
        "created_at": now,
        "updated_at": now,
    }
    activity.append(act_row)

    # persist mutations
    # tasks: update the one task row
    updated = 0
    for i, t in enumerate(tasks):
        if t.get("id") == task.get("id"):
            tasks[i] = task
            updated += 1
            break
    if updated != 1:
        _finish("failed", "Task disappeared during update", resolved)
        return _err("NOT_FOUND", "Task not found", taskId=task.get("id"))

    _save("tasks.json", tasks)
    _save("task_activity.json", activity)

    _finish("succeeded", None, {**resolved, "tagName": tagName})

    return {
        "task": task,
        "removed": {"tagName": tagName, "was_present": had_tag},
        "operation": {
            "id": op["id"],
            "status": "succeeded",
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }
